1	/**
2	 * Mercury Bridge — Configuration
3	 * ══════════════════════════════════════════════════════════════
4	 * Runtime tunables live in mercury.config.json.
5	 * Secrets are read only through explicitly configured env key names.
6	 */
7	
8	'use strict';
9	
10	const fs = require('fs');
11	const path = require('path');
12	
13	// ─── Repo root ────────────────────────────────────────────────
14	const REPO_ROOT = path.resolve(__dirname, '..', '..');
15	const explicitConfigFile = typeof process.env.MERCURY_CONFIG_FILE === 'string'
16	  ? process.env.MERCURY_CONFIG_FILE.trim()
17	  : '';
18	const MERCURY_CONFIG_FILE = explicitConfigFile
19	  ? path.resolve(explicitConfigFile)
20	  : path.join(REPO_ROOT, 'mercury.config.json');
21	const MERCURY_IGNORE_FILE = path.join(REPO_ROOT, 'mercury.ignore');
22	
23	function getConfigValue(config, dottedPath) {
24	  return dottedPath.split('.').reduce((current, key) => (
25	    current && Object.prototype.hasOwnProperty.call(current, key) ? current[key] : undefined
26	  ), config);
27	}
28	
29	function readMercuryConfig(filePath) {
30	  if (!fs.existsSync(filePath)) {
31	    throw new Error(`Missing Mercury config contract: ${filePath}`);
32	  }
33	  try {
34	    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
35	  } catch (err) {
36	    throw new Error(`Invalid Mercury config JSON at ${filePath}: ${err.message}`);
37	  }
38	}
39	
40	function requiredString(config, dottedPath) {
41	  const value = getConfigValue(config, dottedPath);
42	  if (typeof value !== 'string' || value.trim() === '') {
43	    throw new Error(`Missing mercury.config.json value: ${dottedPath}`);
44	  }
45	  return value.trim();
46	}
47	
48	function optionalString(config, dottedPath) {
49	  const value = getConfigValue(config, dottedPath);
50	  if (value == null || value === '') return null;
51	  if (typeof value !== 'string') {
52	    throw new Error(`Invalid mercury.config.json value: ${dottedPath} must be a string`);
53	  }
54	  return value.trim();
55	}
56	
57	function requiredBoolean(config, dottedPath) {
58	  const value = getConfigValue(config, dottedPath);
59	  if (typeof value !== 'boolean') {
60	    throw new Error(`Invalid mercury.config.json value: ${dottedPath} must be a boolean`);
61	  }
62	  return value;
63	}
64	
65	function optionalBoolean(config, dottedPath, defaultValue) {
66	  const value = getConfigValue(config, dottedPath);
67	  if (value == null) return defaultValue;
68	  if (typeof value !== 'boolean') {
69	    throw new Error(`Invalid mercury.config.json value: ${dottedPath} must be a boolean`);
70	  }
71	  return value;
72	}
73	
74	function optionalEnvBoolean(envName) {
75	  if (!Object.prototype.hasOwnProperty.call(process.env, envName)) return null;
76	  const value = String(process.env[envName] || '').trim().toLowerCase();
77	  if (value === '') return null;
78	  if (['1', 'true', 'yes', 'on'].includes(value)) return true;
79	  if (['0', 'false', 'no', 'off'].includes(value)) return false;
80	  return false;
81	}
82	
83	function requiredNumber(config, dottedPath, { integer = false, min = Number.NEGATIVE_INFINITY } = {}) {
84	  const value = getConfigValue(config, dottedPath);
85	  if (typeof value !== 'number' || !Number.isFinite(value)) {
86	    throw new Error(`Invalid mercury.config.json value: ${dottedPath} must be a finite number`);
87	  }
88	  if (integer && !Number.isInteger(value)) {
89	    throw new Error(`Invalid mercury.config.json value: ${dottedPath} must be an integer`);
90	  }
91	  if (value < min) {
92	    throw new Error(`Invalid mercury.config.json value: ${dottedPath} must be >= ${min}`);
93	  }
94	  return value;
95	}
96	
97	function optionalNumber(config, dottedPath, defaultValue, options = {}) {
98	  const value = getConfigValue(config, dottedPath);
99	  if (value == null) return defaultValue;
100	  return requiredNumber(config, dottedPath, options);
101	}
102	
103	function requiredText(config, dottedPath) {
104	  const value = getConfigValue(config, dottedPath);
105	  if (typeof value === 'string' && value.trim() !== '') {
106	    return value.trim();
107	  }
108	  if (Array.isArray(value) && value.every((line) => typeof line === 'string')) {
109	    const joined = value.join('\n').trim();
110	    if (joined !== '') return joined;
111	  }
112	  throw new Error(`Missing mercury.config.json text value: ${dottedPath}`);
113	}
114	
115	function optionalText(config, dottedPath, defaultValue) {
116	  const value = getConfigValue(config, dottedPath);
117	  if (value == null || value === '') return defaultValue;
118	  return requiredText(config, dottedPath);
119	}
120	
121	function optionalPlainObject(config, dottedPath, defaultValue = null) {
122	  const value = getConfigValue(config, dottedPath);
123	  if (value == null) return defaultValue;
124	  if (typeof value !== 'object' || Array.isArray(value)) {
125	    throw new Error(`Invalid mercury.config.json value: ${dottedPath} must be an object`);
126	  }
127	  return JSON.parse(JSON.stringify(value));
128	}
129	
130	function loadMercuryIgnore(filePath) {
131	  if (!fs.existsSync(filePath)) {
132	    throw new Error(`Missing Mercury ignore contract: ${filePath}`);
133	  }
134	
135	  const skipDirs = new Set();
136	  const lines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
137	  for (const [idx, rawLine] of lines.entries()) {
138	    const line = rawLine.trim();
139	    if (!line || line.startsWith('#')) continue;
140	    if (!line.endsWith('/')) {
141	      throw new Error(`Invalid mercury.ignore line ${idx + 1}: directory entries must end with /`);
142	    }
143	    if (line.includes('*')) {
144	      throw new Error(`Invalid mercury.ignore line ${idx + 1}: glob entries are not supported`);
145	    }
146	    const normalized = line.replace(/\\/g, '/').replace(/\/+$/, '');
147	    const segments = normalized.split('/').filter(Boolean);
148	    const dirName = segments[segments.length - 1];
149	    if (!dirName || dirName === '.' || dirName === '..') {
150	      throw new Error(`Invalid mercury.ignore line ${idx + 1}: ${rawLine}`);
151	    }
152	    skipDirs.add(dirName);
153	  }
154	
155	  if (skipDirs.size === 0) {
156	    throw new Error(`Mercury ignore contract is empty: ${filePath}`);
157	  }
158	
159	  return { skipDirs };
160	}
161	
162	function isPathIgnoredByMercury(pathLike, skipDirs = SKIP_DIRS) {
163	  if (!pathLike || typeof pathLike !== 'string') return false;
164	  const parts = pathLike.replace(/\\/g, '/').split('/').filter(Boolean);
165	  return parts.some(part => skipDirs.has(part));
166	}
167	
168	const MERCURY_CONFIG = readMercuryConfig(MERCURY_CONFIG_FILE);
169	
170	// ─── Embeddings ───────────────────────────────────────────────
171	const EMBED_PROVIDER = requiredString(MERCURY_CONFIG, 'embeddings.provider').toLowerCase();
172	
173	// ─── MongoDB ──────────────────────────────────────────────────
174	const MONGO_URI = requiredString(MERCURY_CONFIG, 'mongo.uri');
175	const MONGO_DB_NAME = requiredString(MERCURY_CONFIG, 'mongo.dbName');
176	const MONGO_COLLECTION_CHUNKS = requiredString(MERCURY_CONFIG, 'mongo.chunksCollection');
177	const MONGO_COLLECTION_STATS = requiredString(MERCURY_CONFIG, 'mongo.statsCollection');
178	
179	const EMBED_ENDPOINT = requiredString(MERCURY_CONFIG, 'embeddings.endpoint');
180	const EMBED_MODEL = requiredString(MERCURY_CONFIG, 'embeddings.model');
181	const EMBED_API_KEY_ENV = optionalString(MERCURY_CONFIG, 'embeddings.apiKeyEnv');
182	let EMBED_API_KEY = '';
183	
184	if (!['openai-compatible', 'ollama'].includes(EMBED_PROVIDER)) {
185	  throw new Error(`Unsupported EMBED_PROVIDER=${EMBED_PROVIDER}. Use openai-compatible or ollama.`);
186	}
187	
188	if (EMBED_PROVIDER === 'openai-compatible') {
189	  if (!EMBED_API_KEY_ENV) {
190	    throw new Error('embeddings.apiKeyEnv is required when EMBED_PROVIDER=openai-compatible');
191	  }
192	  EMBED_API_KEY = process.env[EMBED_API_KEY_ENV];
193	  if (!EMBED_API_KEY) {
194	    throw new Error(`Configured embedding API key env is missing: ${EMBED_API_KEY_ENV}`);
195	  }
196	} else if (EMBED_API_KEY_ENV) {
197	  throw new Error('embeddings.apiKeyEnv must be empty when EMBED_PROVIDER=ollama');
198	}
199	
200	if (EMBED_PROVIDER === 'ollama') {
201	  const endpointUrl = new URL(EMBED_ENDPOINT);
202	  const localHosts = new Set(['localhost', '127.0.0.1', '::1']);
203	  if (!localHosts.has(endpointUrl.hostname)) {
204	    throw new Error(`EMBED_PROVIDER=ollama requires a local endpoint, got ${EMBED_ENDPOINT}. Set embeddings.endpoint in mercury.config.json.`);
205	  }
206	}
207	
208	function slugEmbedIndexPart(value) {
209	  return String(value == null ? '' : value)
210	    .trim()
211	    .toLowerCase()
212	    .replace(/[^a-z0-9]+/g, '_')
213	    .replace(/^_+|_+$/g, '');
214	}
215	
216	function normalizeEmbedEndpointIdentity(endpoint) {
217	  let parsed;
218	  try {
219	    parsed = new URL(endpoint);
220	  } catch (err) {
221	    throw new Error(`Invalid EMBED_ENDPOINT=${endpoint}`);
222	  }
223	  if (parsed.username || parsed.password || parsed.search || parsed.hash) {
224	    throw new Error('EMBED_ENDPOINT must not contain credentials, query parameters, or fragments');
225	  }
226	  const trimmedPathname = parsed.pathname.replace(/\/+$/, '');
227	  const pathname = trimmedPathname === '' ? '/' : trimmedPathname;
228	  return `${parsed.protocol}//${parsed.host.toLowerCase()}${pathname}`;
229	}
230	
231	const EMBED_DIMENSIONS = requiredNumber(MERCURY_CONFIG, 'embeddings.dimensions', { integer: true, min: 1 });
232	const EMBED_ENDPOINT_ID = normalizeEmbedEndpointIdentity(EMBED_ENDPOINT);
233	const EMBED_INDEX_ID = [
234	  slugEmbedIndexPart(EMBED_PROVIDER),
235	  slugEmbedIndexPart(EMBED_ENDPOINT_ID),
236	  slugEmbedIndexPart(EMBED_MODEL),
237	  EMBED_DIMENSIONS,
238	].join('__');
239	
240	// ─── Batching ─────────────────────────────────────────────────
241	const EMBED_BATCH_MAX_CHUNKS = requiredNumber(MERCURY_CONFIG, 'batching.maxChunks', { integer: true, min: 1 });
242	const EMBED_BATCH_MAX_TOKENS = requiredNumber(MERCURY_CONFIG, 'batching.maxTokens', { integer: true, min: 1 });
243	const EMBED_FAIL_ON_BATCH_ERROR = requiredBoolean(MERCURY_CONFIG, 'batching.failOnBatchError');
244	const EMBED_MIN_INTERVAL_MS = requiredNumber(MERCURY_CONFIG, 'batching.minIntervalMs', { integer: true, min: 0 });
245	
246	// ─── Ollama local embedder metadata ──────────────────────────
247	const OLLAMA_URL = EMBED_PROVIDER === 'ollama'
248	  ? new URL(EMBED_ENDPOINT).origin
249	  : null;
250	const OLLAMA_EMBED_MODEL = EMBED_PROVIDER === 'ollama'
251	  ? EMBED_MODEL
252	  : null;
253	
254	// ─── Chunking ─────────────────────────────────────────────────
255	const CHUNK_WINDOW_SIZE = requiredNumber(MERCURY_CONFIG, 'chunking.windowSize', { integer: true, min: 1 });
256	const CHUNK_WINDOW_OVERLAP = requiredNumber(MERCURY_CONFIG, 'chunking.windowOverlap', { integer: true, min: 0 });
257	const MAX_FILE_BYTES = requiredNumber(MERCURY_CONFIG, 'chunking.maxFileBytes', { integer: true, min: 1 });
258	const MAX_CHUNK_CHARS = requiredNumber(MERCURY_CONFIG, 'chunking.maxChunkChars', { integer: true, min: 1 });
259	
260	// ─── Retrieval ────────────────────────────────────────────────
261	const RETRIEVE_TOP_K = requiredNumber(MERCURY_CONFIG, 'retrieval.topK', { integer: true, min: 1 });
262	
263	// ─── Layer 2: Hybrid retrieval ────────────────────────────────
264	// BM25 parameters (Robertson 1995 standard values)
265	const BM25_K1 = requiredNumber(MERCURY_CONFIG, 'retrieval.bm25K1', { min: 0 });
266	const BM25_B = requiredNumber(MERCURY_CONFIG, 'retrieval.bm25B', { min: 0 });
267	
268	// Reciprocal Rank Fusion constant — controls how aggressively low-ranked
269	// results are discounted. Standard value from Cormack et al. 2009.
270	const RRF_K = requiredNumber(MERCURY_CONFIG, 'retrieval.rrfK', { integer: true, min: 1 });
271	
272	// How many candidates each scorer returns before RRF merge
273	const HYBRID_CANDIDATE_POOL = requiredNumber(MERCURY_CONFIG, 'retrieval.hybridCandidatePool', { integer: true, min: 1 });
274	
275	// Content-type boost multipliers applied to RRF score.
276	const CONTENT_TYPE_BOOST_STRONG = requiredNumber(MERCURY_CONFIG, 'retrieval.contentTypeBoostStrong', { min: 0 });
277	const CONTENT_TYPE_BOOST_WEAK = requiredNumber(MERCURY_CONFIG, 'retrieval.contentTypeBoostWeak', { min: 0 });
278	
279	const HYBRID_ENABLED = requiredBoolean(MERCURY_CONFIG, 'retrieval.hybridEnabled');
280	
281	// ─── Investigation trace memory ──────────────────────────────
282	const TRACE_MEMORY_ENABLED = requiredBoolean(MERCURY_CONFIG, 'traceMemory.enabled');
283	const TRACE_COLLECTION = requiredString(MERCURY_CONFIG, 'traceMemory.collection');
284	const TRACE_CAPTURE_MODE = requiredString(MERCURY_CONFIG, 'traceMemory.captureMode').toLowerCase();
285	const TRACE_INJECT_THRESHOLD = requiredNumber(MERCURY_CONFIG, 'traceMemory.injectThreshold', { min: 0 });
286	const TRACE_DEDUP_THRESHOLD = requiredNumber(MERCURY_CONFIG, 'traceMemory.dedupThreshold', { min: 0 });
287	const TRACE_STALE_DAYS = requiredNumber(MERCURY_CONFIG, 'traceMemory.staleDays', { integer: true, min: 0 });
288	const TRACE_MAX_COUNT = requiredNumber(MERCURY_CONFIG, 'traceMemory.maxCount', { integer: true, min: 1 });
289	const TRACE_PROTECTED_USAGE_COUNT = requiredNumber(MERCURY_CONFIG, 'traceMemory.protectedUsageCount', { integer: true, min: 0 });
290	const supportedTraceCaptureModes = new Set(['manual']);
291	if (!supportedTraceCaptureModes.has(TRACE_CAPTURE_MODE)) {
292	  throw new Error(`Unsupported traceMemory.captureMode=${TRACE_CAPTURE_MODE}. Use manual.`);
293	}
294	
295	// ─── Mercury LLM client ───────────────────────────────────────
296	const MERCURY_LLM_PROVIDER = requiredString(MERCURY_CONFIG, 'llm.provider').toLowerCase();
297	const MERCURY_LLM_BASE_URL = requiredString(MERCURY_CONFIG, 'llm.baseUrl');
298	const MERCURY_LLM_MODEL = requiredString(MERCURY_CONFIG, 'llm.model');
299	const MERCURY_LLM_API_KEY_ENV = optionalString(MERCURY_CONFIG, 'llm.apiKeyEnv');
300	const MERCURY_LLM_CLIENT_MAX_TOKENS = requiredNumber(MERCURY_CONFIG, 'llm.clientMaxTokens', { integer: true, min: 1 });
301	const MERCURY_LLM_CLIENT_MIN_TOKENS = requiredNumber(MERCURY_CONFIG, 'llm.clientMinTokens', { integer: true, min: 0 });
302	const MERCURY_LLM_REQUEST_TIMEOUT_MS = requiredNumber(MERCURY_CONFIG, 'llm.requestTimeoutMs', { integer: true, min: 1000 });
303	const MERCURY_LLM_TEMPERATURE = requiredNumber(MERCURY_CONFIG, 'llm.temperature', { min: 0 });
304	const AGENTIC_MAX_ITERATIONS = requiredNumber(MERCURY_CONFIG, 'agentic.maxIterations', { integer: true, min: 1 });
305	const AGENTIC_MAX_TOKENS = requiredNumber(MERCURY_CONFIG, 'agentic.maxTokens', { integer: true, min: 1 });
306	const SINGLE_SHOT_MAX_TOKENS = requiredNumber(MERCURY_CONFIG, 'singleShot.maxTokens', { integer: true, min: 1 });
307	const AGENTIC_SYSTEM_PROMPT = requiredText(MERCURY_CONFIG, 'agentic.systemPrompt');
308	const MERCURY_SYSTEM_PROMPT = requiredText(MERCURY_CONFIG, 'singleShot.systemPrompt');
309	
310	const supportedLlmProviders = new Set(['mercury', 'ollamacloud', 'openai', 'claude', 'ollama']);
311	if (!supportedLlmProviders.has(MERCURY_LLM_PROVIDER)) {
312	  throw new Error(`Unsupported llm.provider=${MERCURY_LLM_PROVIDER}. Use ${Array.from(supportedLlmProviders).join(', ')}.`);
313	}
314	try {
315	  const llmBaseUrl = new URL(MERCURY_LLM_BASE_URL);
316	  if (llmBaseUrl.username || llmBaseUrl.password || llmBaseUrl.search || llmBaseUrl.hash) {
317	    throw new Error('llm.baseUrl must not contain credentials, query parameters, or fragments');
318	  }
319	} catch (err) {
320	  throw new Error(`Invalid mercury.config.json value: llm.baseUrl: ${err.message}`);
321	}
322	if (MERCURY_LLM_PROVIDER === 'ollama') {
323	  if (MERCURY_LLM_API_KEY_ENV) {
324	    throw new Error('llm.apiKeyEnv must be empty when llm.provider=ollama');
325	  }
326	} else if (!MERCURY_LLM_API_KEY_ENV) {
327	  throw new Error('llm.apiKeyEnv is required for non-local Mercury LLM providers');
328	}
329	
330	// ─── Fable adversarial review client ─────────────────────────
331	const CONSENSUS_DEFAULT_ENABLED = optionalBoolean(MERCURY_CONFIG, 'consensus.defaultEnabled', false);
332	const adversarialReviewEnv = optionalEnvBoolean('MERCURY_ADVERSARIAL_REVIEW');
333	const ADVERSARIAL_REVIEW_DEFAULT_ENABLED = adversarialReviewEnv == null
334	  ? optionalBoolean(MERCURY_CONFIG, 'adversarialReview.defaultEnabled', false)
335	  : adversarialReviewEnv;
336	const ADVERSARIAL_REVIEW_MAX_RECHECKS = optionalNumber(MERCURY_CONFIG, 'adversarialReview.maxRechecks', 2, { integer: true, min: 0 });
337	const CONSENSUS_PROVIDER = (optionalString(MERCURY_CONFIG, 'consensus.provider') || 'claude').toLowerCase();
338	const CONSENSUS_BASE_URL = optionalString(MERCURY_CONFIG, 'consensus.baseUrl') || 'https://api.anthropic.com/v1';
339	const CONSENSUS_MODEL = optionalString(MERCURY_CONFIG, 'consensus.model') || 'claude-fable-5';
340	const CONSENSUS_API_KEY_ENV = optionalString(MERCURY_CONFIG, 'consensus.apiKeyEnv');
341	const CONSENSUS_COMMAND = optionalString(MERCURY_CONFIG, 'consensus.command') || 'claude';
342	const CONSENSUS_PERMISSION_MODE = optionalString(MERCURY_CONFIG, 'consensus.permissionMode') || 'dontAsk';
343	const CONSENSUS_CLIENT_MAX_TOKENS = optionalNumber(MERCURY_CONFIG, 'consensus.clientMaxTokens', 2000, { integer: true, min: 1 });
344	const CONSENSUS_CLIENT_MIN_TOKENS = optionalNumber(MERCURY_CONFIG, 'consensus.clientMinTokens', 0, { integer: true, min: 0 });
345	const CONSENSUS_REQUEST_TIMEOUT_MS = optionalNumber(MERCURY_CONFIG, 'consensus.requestTimeoutMs', 300000, { integer: true, min: 1000 });
346	const CONSENSUS_TEMPERATURE = optionalNumber(MERCURY_CONFIG, 'consensus.temperature', 0, { min: 0 });
347	const CONSENSUS_OPENAI_EXTRA_BODY = optionalPlainObject(MERCURY_CONFIG, 'consensus.openaiExtraBody', {});
348	const CONSENSUS_SYSTEM_PROMPT = optionalText(MERCURY_CONFIG, 'consensus.systemPrompt', [
349	  'You are Fable, the consensus collaborator for OGZPrime Mercury reviews.',
350	  'Evaluate Mercury evidence. Do not invent repo facts or file:line citations.',
351	].join('\n'));
352	
353	const supportedConsensusProviders = new Set([...supportedLlmProviders, 'claude-code']);
354	if (!supportedConsensusProviders.has(CONSENSUS_PROVIDER)) {
355	  throw new Error(`Unsupported consensus.provider=${CONSENSUS_PROVIDER}. Use ${Array.from(supportedConsensusProviders).join(', ')}.`);
356	}
357	if (CONSENSUS_PROVIDER !== 'claude-code') {
358	  try {
359	    const consensusBaseUrl = new URL(CONSENSUS_BASE_URL);
360	    if (consensusBaseUrl.username || consensusBaseUrl.password || consensusBaseUrl.search || consensusBaseUrl.hash) {
361	      throw new Error('consensus.baseUrl must not contain credentials, query parameters, or fragments');
362	    }
363	  } catch (err) {
364	    throw new Error(`Invalid mercury.config.json value: consensus.baseUrl: ${err.message}`);
365	  }
366	}
367	if (CONSENSUS_PROVIDER === 'ollama') {
368	  if (CONSENSUS_API_KEY_ENV) {
369	    throw new Error('consensus.apiKeyEnv must be empty when consensus.provider=ollama');
370	  }
371	  try {
372	    const consensusBaseUrl = new URL(CONSENSUS_BASE_URL);
373	    if (!['localhost', '127.0.0.1', '::1'].includes(consensusBaseUrl.hostname)) {
374	      throw new Error(`consensus.provider=ollama requires a local endpoint, got ${CONSENSUS_BASE_URL}`);
375	    }
376	  } catch (err) {
377	    throw new Error(`Invalid mercury.config.json value: consensus.baseUrl: ${err.message}`);
378	  }
379	} else if (CONSENSUS_PROVIDER === 'claude-code') {
380	  if (CONSENSUS_API_KEY_ENV) {
381	    throw new Error('consensus.apiKeyEnv must be empty when consensus.provider=claude-code');
382	  }
383	} else {
384	  if (!CONSENSUS_API_KEY_ENV) {
385	    throw new Error(`consensus.apiKeyEnv is required when consensus.provider=${CONSENSUS_PROVIDER}`);
386	  }
387	}
388	
389	// ─── Skip patterns ────────────────────────────────────────────
390	// Directory exclusions live in mercury.ignore so intake/history boundaries are
391	// visible and shared by the indexer, Mercury grep, and legacy repo search.
392	const { skipDirs: SKIP_DIRS } = loadMercuryIgnore(MERCURY_IGNORE_FILE);
393	
394	const SKIP_FILE_EXTENSIONS = new Set([
395	  '.png', '.jpg', '.jpeg', '.gif', '.webp', '.svg', '.ico',
396	  '.pdf', '.zip', '.gz', '.tar', '.rar', '.7z',
397	  '.mp4', '.mp3', '.wav', '.mov',
398	  '.lock', '.lockb',
399	  '.log',
400	]);
401	
402	const SKIP_FILE_PATTERNS = [
403	  /\.bak$/,
404	  /\.bak-/,
405	  /\.backup$/,
406	  /^PROOF-.*\.json$/,
407	
408	  /\.min\.js$/,
409	  /package-lock\.json$/,
410	  /yarn\.lock$/,
411	  /call-graph-cache\.json$/,
412	  /rag_index\.json$/,
413	  /todocontext\d+\.md$/,
414	  /\.last-rag-query\.json$/,
415	  /MISSION-.*\.md$/,
416	  /backtest-report-.*\.json$/,
417	  /equity_\d{4}.*\.json$/,
418	  /metrics_\d{4}.*\.json$/,
419	  /trades_\d{4}.*\.json$/,
420	  /debug-.*\.js$/,
421	  /tuning-report-.*\.json$/,
422	  /round\d+-results\.json$/,
423	  /mission0\.md$/,
424	  /claudito-cognition-refactor-plan\.md$/,
425	];
426	
427	const INDEX_FILE_EXTENSIONS = new Set([
428	  '.js', '.mjs', '.cjs',
429	  '.md',
430	  '.json',    // only small config/docs, guarded by file size
431	  '.jsonl',   // structured records (fixes.jsonl, etc.)
432	]);
433	
434	module.exports = {
435	  REPO_ROOT,
436	  MONGO_URI,
437	  MONGO_DB_NAME,
438	  MONGO_COLLECTION_CHUNKS,
439	  MONGO_COLLECTION_STATS,
440	  MERCURY_CONFIG_FILE,
441	  readMercuryConfig,
442	  MERCURY_IGNORE_FILE,
443	  loadMercuryIgnore,
444	  EMBED_PROVIDER,
445	  EMBED_ENDPOINT,
446	  EMBED_ENDPOINT_ID,
447	  EMBED_MODEL,
448	  EMBED_DIMENSIONS,
449	  EMBED_INDEX_ID,
450	  EMBED_API_KEY,
451	  EMBED_BATCH_MAX_CHUNKS,
452	  EMBED_BATCH_MAX_TOKENS,
453	  EMBED_FAIL_ON_BATCH_ERROR,
454	  EMBED_MIN_INTERVAL_MS,
455	  OLLAMA_URL,
456	  OLLAMA_EMBED_MODEL,
457	  CHUNK_WINDOW_SIZE,
458	  CHUNK_WINDOW_OVERLAP,
459	  MAX_FILE_BYTES,
