3	const fs = require('fs');
4	const path = require('path');
5	const ignorePolicy = require('./ignore-policy.json');
6	
7	const REPO_ROOT = path.resolve(__dirname, '..', '..');
8	
9	// Claude bridge uses a cloned ignore-policy snapshot. It must not import or
10	// mutate Mercury runtime modules; Mercury owns Mercury state.
11	//
12	// .claude/memory/ is the canonical Claude persistent memory store. It is a
13	// real directory inside the repo (allowed via .claude/ prefix). The harness
14	// reads it via the legacy $HOME path which is a symlink pointing here; the
15	// resolveRealPath() call below dereferences that symlink before policy check
16	// so paths that look outside-repo but actually resolve inside-repo are allowed
17	// while genuinely outside-repo paths stay blocked.
18	const CLAUDE_ALLOW_PREFIXES = normalizePolicyList(ignorePolicy.allowedPrefixes, 'allowedPrefixes');
19	const IGNORED_DIRECTORIES = normalizePolicyList(ignorePolicy.ignoredDirectories, 'ignoredDirectories');
20	const PROTECTED_WRITE_PATHS = Object.freeze([
21	  '.claude/settings.json',
22	  '.claude/settings.local.json',
23	  '.claude/hooks/',
24	  '.claude/hookify.',
25	  '.claude/commands/',
26	  '.claude/session-state/',
27	  'trai_brain/claude-bridge/',
28	]);
29	const PROTECTED_READ_PATHS = Object.freeze([
30	  '.claude/session-state/',
31	]);
32	
33	function normalizePolicyList(values, fieldName) {
34	  if (!Array.isArray(values) || values.length === 0) {
35	    throw new Error(`claude-bridge ignore policy ${fieldName} must be a non-empty array`);
36	  }
37	  return values.map((value) => {
38	    if (typeof value !== 'string' || value.trim() === '') {
39	      throw new Error(`claude-bridge ignore policy ${fieldName} contains a non-string entry`);
40	    }
41	    return value.replace(/\\/g, '/');
42	  });
43	}
44	
45	function resolveRealPath(targetPath) {
46	  // Resolve symlinks if the target exists. If it doesn't (e.g. a new file
47	  // being created), fall back to the literal abs path — Write paths get
48	  // checked before the file exists, so realpathSync would throw otherwise.
49	  try {
50	    return fs.realpathSync(targetPath);
51	  } catch (_) {
52	    return path.resolve(targetPath);
53	  }
54	}
55	
56	function relToRepo(targetPath) {
57	  if (!targetPath || typeof targetPath !== 'string') return null;
58	  const abs = path.isAbsolute(targetPath)
59	    ? targetPath
60	    : path.resolve(REPO_ROOT, targetPath);
61	  const real = resolveRealPath(abs);
62	  const rel = path.relative(REPO_ROOT, real);
63	  if (rel.startsWith('..') || path.isAbsolute(rel)) {
64	    return { outsideRepo: true, rel: null };
65	  }
66	  return { outsideRepo: false, rel: rel.split(path.sep).join('/') };
67	}
68	
69	function isClaudeAllowed(rel) {
70	  return CLAUDE_ALLOW_PREFIXES.some((p) => rel === p.replace(/\/$/, '') || rel.startsWith(p));
71	}
72	
73	function isIgnoredByClaudeBridge(rel) {
74	  const segments = rel.split('/').filter(Boolean);
75	  return IGNORED_DIRECTORIES.some((entry) => {
76	    const dir = entry.replace(/\/$/, '');
77	    return segments.includes(dir);
78	  });
79	}
80	
81	function isProtectedWritePath(rel) {
82	  return PROTECTED_WRITE_PATHS.some((entry) => {
83	    if (entry.endsWith('/')) {
84	      return rel === entry.replace(/\/$/, '') || rel.startsWith(entry);
85	    }
86	    return rel === entry || rel.startsWith(entry);
87	  });
88	}
89	
90	function isProtectedReadPath(rel) {
91	  return PROTECTED_READ_PATHS.some((entry) => {
92	    if (entry.endsWith('/')) {
93	      return rel === entry.replace(/\/$/, '') || rel.startsWith(entry);
94	    }
95	    return rel === entry || rel.startsWith(entry);
96	  });
97	}
98	
99	function normalizeOperation(operation) {
100	  if (operation == null || operation === '') return 'read';
101	  if (operation !== 'read' && operation !== 'write') {
102	    throw new Error(`Unsupported claude-bridge policy operation: ${operation}`);
103	  }
104	  return operation;
105	}
106	
107	function checkPath(targetPath, options = {}) {
108	  const operation = normalizeOperation(options.operation);
109	  const r = relToRepo(targetPath);
110	  if (!r) {
111	    return { allowed: false, reason: 'no_path' };
112	  }
113	  if (r.outsideRepo) {
114	    return { allowed: false, reason: 'outside_repo', path: targetPath };
115	  }
116	  if (operation === 'read' && isProtectedReadPath(r.rel)) {
117	    return { allowed: false, reason: 'claude_bridge_protected_state', path: r.rel };
118	  }
119	  if (operation === 'write' && isProtectedWritePath(r.rel)) {
120	    return { allowed: false, reason: 'claude_bridge_protected_write', path: r.rel };
121	  }
122	  if (isClaudeAllowed(r.rel)) {
123	    return { allowed: true, reason: 'claude_owned', path: r.rel };
124	  }
125	  if (isIgnoredByClaudeBridge(r.rel)) {
126	    return { allowed: false, reason: 'claude_bridge_ignored', path: r.rel };
127	  }
128	  return { allowed: true, reason: 'ok', path: r.rel };
129	}
130	
131	module.exports = {
132	  checkPath,
133	  relToRepo,
134	  isIgnoredByClaudeBridge,
135	  isProtectedReadPath,
136	  isProtectedWritePath,
137	  REPO_ROOT,
138	};
