397	async function callMercuryWithRetry(client, messages, tools, options, verbose) {
398	  const maxRetries = 3;
399	  const baseDelayMs = 500;
400	
401	  for (let attempt = 0; attempt <= maxRetries; attempt++) {
402	    try {
403	      const assistantMsg = await client.generateWithTools(messages, tools, options);
404	
405	      const hasToolCalls = Array.isArray(assistantMsg.tool_calls) && assistantMsg.tool_calls.length > 0;
406	      const hasContent = assistantMsg.content && assistantMsg.content.trim() !== '';
407	
408	      if (!hasToolCalls && !hasContent) {
409	        if (attempt < maxRetries) {
410	          const delay = baseDelayMs * Math.pow(2, attempt) + Math.floor(Math.random() * 200);
411	          if (verbose) console.error(`[REACT] Empty response (no tool_calls, no content), retry ${attempt + 1}/${maxRetries} in ${delay}ms`);
412	          await new Promise(r => setTimeout(r, delay));
413	          continue;
414	        }
415	      }
416	
417	      if (attempt > 0 && verbose) {
418	        console.error(`[REACT] Recovered after ${attempt} retry(ies)`);
419	      }
420	      return assistantMsg;
421	    } catch (err) {
422	      const msg = err.message || String(err);
423	      const isRetriable = /HTTP (429|502|503|504)/.test(msg) || /ECONNRESET|ETIMEDOUT|socket hang up/i.test(msg);
424	      if (isRetriable && attempt < maxRetries) {
425	        const delay = baseDelayMs * Math.pow(2, attempt) + Math.floor(Math.random() * 200);
426	        if (verbose) console.error(`[REACT] ${msg.slice(0, 120)}, retry ${attempt + 1}/${maxRetries} in ${delay}ms`);
427	        await new Promise(r => setTimeout(r, delay));
428	        continue;
429	      }
430	      throw err;
431	    }
432	  }
433	  throw new Error('callMercuryWithRetry: max retries exceeded');
434	}
