1640	  async function tavily_search(args) {
1641	    const TAVILY_API_KEY = process.env.TAVILY_API_KEY || '';
1642	    const query = (args && args.query) || '';
1643	    const maxResults = Math.min(Math.max(parseInt(args.max_results || 5, 10), 1), 10);
1644	
1645	    if (!query || typeof query !== 'string') {
1646	      return { error: 'tavily_search requires a non-empty query string' };
1647	    }
1648	    if (!TAVILY_API_KEY) {
1649	      return {
1650	        error: 'tavily_search requires TAVILY_API_KEY in environment (free tier at tavily.com)',
1651	      };
1652	    }
1653	
1654	    try {
1655	      const response = await fetch('https://api.tavily.com/search', {
1656	        method: 'POST',
1657	        headers: { 'Content-Type': 'application/json' },
1658	        body: JSON.stringify({
1659	          api_key: TAVILY_API_KEY,
1660	          query,
1661	          search_depth: 'basic',
1662	          max_results: maxResults,
1663	          include_answer: true,
1664	          include_raw_content: false,
1665	        }),
1666	      });
1667	
1668	      if (!response.ok) {
1669	        return { error: `tavily API returned ${response.status}` };
1670	      }
1671	      const data = await response.json();
1672	      return {
1673	        query,
1674	        answer: data.answer || null,
1675	        results: (data.results || []).slice(0, maxResults).map(r => ({
1676	          title: r.title,
1677	          url: r.url,
1678	          snippet: (r.content || '').substring(0, 400),
1679	        })),
1680	      };
1681	    } catch (err) {
1682	      return { error: `tavily search failed: ${err.message}` };
1683	    }
