21	
22	function optionalPositiveInteger(value, name) {
23	  if (value == null) return null;
24	  if (!Number.isInteger(value) || value < 1) {
25	    throw new Error(`${name} must be a positive integer`);
26	  }
27	  return value;
28	}
29	
30	function configExactInteger(value, configuredValue, name) {
31	  if (value == null) return configuredValue;
32	  const parsed = optionalPositiveInteger(value, name);
33	  if (parsed !== configuredValue) {
34	    throw new Error(`${name} must match mercury.config.json value ${configuredValue}`);
35	  }
36	  return configuredValue;
37	}
