39	function assertRetrievableChunkPath(chunk, source) {
40	  const id = chunk && chunk._id ? String(chunk._id) : 'unknown';
41	  if (!chunk || !chunk.file_path) {
42	    throw new Error(`Mercury retrieval ${source} chunk ${id} is missing file_path; cannot enforce mercury.ignore`);
43	  }
44	  if (config.isPathIgnoredByMercury(chunk.file_path)) {
45	    throw new Error(`Mercury retrieval ${source} contains ignored path ${chunk.file_path}; reindex required`);
46	  }
47	}
48	
49	// ─────────────────────────────────────────────────────────────
50	// COSINE SIMILARITY
51	// ─────────────────────────────────────────────────────────────
52	
53	function cosineSimilarity(a, b) {
54	  if (a.length !== b.length) {
55	    throw new Error(`Vector length mismatch: ${a.length} vs ${b.length}`);
56	  }
57	  let dot = 0;
58	  let normA = 0;
59	  let normB = 0;
60	  for (let i = 0; i < a.length; i++) {
61	    dot += a[i] * b[i];
62	    normA += a[i] * a[i];
63	    normB += b[i] * b[i];
64	  }
65	  const denom = Math.sqrt(normA) * Math.sqrt(normB);
66	  if (denom === 0) return 0;
67	  return dot / denom;
68	}
