74	/**
75	 * Tokenize text into lowercase terms. Simple whitespace + punctuation split.
76	 * Good enough for BM25 on code — doesn't need a full NLP tokenizer.
77	 */
78	function tokenize(text) {
79	  return text.toLowerCase().replace(/[^a-z0-9_]/g, ' ').split(/\s+/).filter(t => t.length > 1);
80	}
81	
82	/**
83	 * Build BM25 index from an array of chunks.
84	 * Returns { idf, avgDl, docLengths, docTermFreqs } needed for scoring.
85	 */
86	function buildBM25Index(chunks) {
87	  const N = chunks.length;
88	  const df = {};  // document frequency: term -> count of docs containing it
89	  const docTermFreqs = [];  // per-doc term frequencies
90	  const docLengths = [];
91	  let totalLength = 0;
92	
93	  for (let i = 0; i < chunks.length; i++) {
94	    const terms = tokenize(chunks[i].text || '');
95	    docLengths.push(terms.length);
96	    totalLength += terms.length;
97	
98	    const tf = {};
99	    const seen = new Set();
100	    for (const t of terms) {
101	      tf[t] = (tf[t] || 0) + 1;
102	      if (!seen.has(t)) {
103	        df[t] = (df[t] || 0) + 1;
104	        seen.add(t);
105	      }
106	    }
107	    docTermFreqs.push(tf);
108	  }
109	
110	  const avgDl = totalLength / N;
111	
112	  // IDF: log((N - df + 0.5) / (df + 0.5) + 1)
113	  const idf = {};
114	  for (const [term, docFreq] of Object.entries(df)) {
115	    idf[term] = Math.log((N - docFreq + 0.5) / (docFreq + 0.5) + 1);
116	  }
117	
118	  return { idf, avgDl, docLengths, docTermFreqs };
119	}
120	
121	/**
122	 * Score a single document against a query using BM25.
123	 */
124	function scoreBM25(queryTerms, docIdx, bm25Index) {
125	  const { idf, avgDl, docLengths, docTermFreqs } = bm25Index;
126	  const k1 = config.BM25_K1;
127	  const b = config.BM25_B;
128	  const dl = docLengths[docIdx];
129	  const tf = docTermFreqs[docIdx];
130	
131	  let score = 0;
132	  for (const qt of queryTerms) {
133	    const termIdf = idf[qt] || 0;
134	    const termTf = tf[qt] || 0;
135	    const num = termTf * (k1 + 1);
136	    const den = termTf + k1 * (1 - b + b * (dl / avgDl));
137	    score += termIdf * (num / den);
138	  }
139	  return score;
140	}
141	
142	// ─────────────────────────────────────────────────────────────
143	// CODE-FLAVORED QUERY DETECTION + KIND MODIFIER
144	// ─────────────────────────────────────────────────────────────
145	
146	/**
147	 * Detect whether a query looks code-flavored (camelCase, snake_case,
148	 * dotted identifiers, code keywords, file extensions). When true,
149	 * kind-based modifiers are applied during RRF merge so actual code
150	 * chunks outrank prose docs that mention the same tokens.
151	 */
152	function isCodeFlavoredQuery(query) {
153	  if (!query || typeof query !== 'string') return false;
154	  if (/[a-z][A-Z]/.test(query)) return true;                    // camelCase
155	  if (/[a-zA-Z]_[a-zA-Z]/.test(query)) return true;             // snake_case
156	  if (/\b\w+\.\w+\b/.test(query)) return true;                  // dotted
157	  const codeKeywords = /\b(function|class|method|variable|const|let|return|import|require|module|export|interface|enum|async|await|throw|catch)\b/i;
158	  if (codeKeywords.test(query)) return true;
159	  if (/\.(js|ts|mjs|cjs|json|jsonl|md|py|sh)\b/i.test(query)) return true;
160	  return false;
161	}
162	
163	const KIND_MODIFIER_CODE_QUERY = {
164	  doc_section: 0.7,
165	  method: 1.3,
166	  'function': 1.3,
167	  jsonl_record: 1.1,
168	  json: 1.0,
169	  window: 1.0,
170	};
171	
172	// ─────────────────────────────────────────────────────────────
173	// QUERY CLASSIFIER
174	// ─────────────────────────────────────────────────────────────
175	
176	/**
177	 * Lightweight heuristic classifier that determines which content_types
178	 * should get a boost for this query. Returns a map of content_type → multiplier.
179	 */
180	function classifyQuery(query) {
181	  const q = query.toLowerCase();
182	  const boosts = {};
183	
184	  // Historical / debugging questions → boost canonical landmine/recent-change docs
185	  if (/\b(bug|fix|broke|crash|error|fail|issue|landmine|gotcha)\b/.test(q) ||
186	      /\b(have we|has there|ever been|previously|before|history|historical)\b/.test(q)) {
187	    boosts['landmine'] = config.CONTENT_TYPE_BOOST_WEAK;
188	    boosts['recent_changes'] = config.CONTENT_TYPE_BOOST_WEAK;
189	  }
190	
191	  // Architecture / design questions → boost project_context + guardrails
192	  if (/\b(architect|design|overview|purpose|vision|how does .* work|module|layer)\b/.test(q)) {
193	    boosts['project_context'] = config.CONTENT_TYPE_BOOST_STRONG;
194	    boosts['guardrails'] = config.CONTENT_TYPE_BOOST_WEAK;
195	  }
196	
197	  // Rules / safety questions → boost guardrails
198	  if (/\b(rule|guardrail|forbidden|never|must not|safety|allowed)\b/.test(q)) {
199	    boosts['guardrails'] = config.CONTENT_TYPE_BOOST_STRONG;
200	    boosts['landmine'] = config.CONTENT_TYPE_BOOST_WEAK;
201	  }
202	
203	  // Changelog / what changed questions → boost changelog + recent_changes
204	  if (/\b(change|changelog|recent|latest|what.*changed|update|commit)\b/.test(q)) {
205	    boosts['changelog'] = config.CONTENT_TYPE_BOOST_STRONG;
206	    boosts['recent_changes'] = config.CONTENT_TYPE_BOOST_STRONG;
207	  }
208	
209	  return boosts;
210	}
211	
212	// ─────────────────────────────────────────────────────────────
213	// RECIPROCAL RANK FUSION
214	// ─────────────────────────────────────────────────────────────
215	
216	/**
217	 * Merge two ranked lists via Reciprocal Rank Fusion.
218	 * Each item appears at most once in the output, scored by:
219	 *   RRF_score = sum over lists of 1 / (k + rank_in_list)
220	 *
221	 * Then apply content_type boost multipliers from classifyQuery.
222	 */
223	function rrfMerge(semanticRanked, bm25Ranked, boosts, k) {
224	  const scores = new Map();  // chunkIdx → RRF score
225	
226	  for (let i = 0; i < semanticRanked.length; i++) {
227	    const idx = semanticRanked[i].idx;
228	    scores.set(idx, (scores.get(idx) || 0) + 1 / (k + i + 1));
229	  }
230	
231	  for (let i = 0; i < bm25Ranked.length; i++) {
232	    const idx = bm25Ranked[i].idx;
233	    scores.set(idx, (scores.get(idx) || 0) + 1 / (k + i + 1));
234	  }
235	
236	  // Apply content_type boost
237	  if (Object.keys(boosts).length > 0) {
238	    for (const [idx, score] of scores) {
239	      const ct = semanticRanked.find(s => s.idx === idx)?.contentType ||
240	                 bm25Ranked.find(s => s.idx === idx)?.contentType ||
241	                 'general';
242	      const mult = boosts[ct] || 1.0;
243	      scores.set(idx, score * mult);
244	    }
245	  }
246	
247	  // Sort by RRF score descending
248	  return [...scores.entries()]
249	    .sort((a, b) => b[1] - a[1])
250	    .map(([idx, score]) => ({ idx, score }));
251	}
252	
253	// ─────────────────────────────────────────────────────────────
254	// HYBRID RETRIEVAL
255	// ─────────────────────────────────────────────────────────────
256	
257	/**
258	 * Retrieve top-K chunks.
259	 *
260	 * Modes (via opts.retrievalMode):
261	 *   'semantic'           — pure cosine similarity (Layer 1 behavior)
262	 *   'hybrid'             — BM25 + semantic + RRF, NO auto-classifier boost
263	 *   'hybrid-classified'  — full Layer 2: BM25 + semantic + RRF + classifyQuery boost
264	 *   null/undefined       — uses config.HYBRID_ENABLED to pick hybrid-classified or semantic
265	 *
266	 * opts.boostType: manual content_type to boost (e.g. 'recent_changes'). Takes
267	 * priority over classifyQuery auto-detection.
268	 */
269	async function retrieveTopK(store, queryEmbedding, k, query, opts = {}) {
270	  const allChunks = await store.fetchAllForScoring();
271	  allChunks.forEach((chunk) => assertRetrievableChunkPath(chunk, 'scoring'));
272	  if (allChunks.length === 0) return [];
273	
274	  const pool = config.HYBRID_CANDIDATE_POOL;
275	
276	  // Determine effective mode
277	  let mode = opts.retrievalMode || (config.HYBRID_ENABLED ? 'hybrid-classified' : 'semantic');
278	
279	  // --- Semantic scoring (always needed) ---
280	  const semanticScored = [];
281	  for (let i = 0; i < allChunks.length; i++) {
282	    const chunk = allChunks[i];
283	    if (!chunk.embedding || chunk.embedding.length !== queryEmbedding.length) continue;
284	    const sim = cosineSimilarity(queryEmbedding, chunk.embedding);
285	    semanticScored.push({ idx: i, sim, contentType: chunk.content_type || 'general' });
286	  }
287	  semanticScored.sort((a, b) => b.sim - a.sim);
288	  const semanticTop = semanticScored.slice(0, pool);
289	
290	  // --- Pure semantic mode ---
291	  if (mode === 'semantic' || !query) {
292	    const topK = semanticTop.slice(0, k);
293	    const topIds = topK.map(s => allChunks[s.idx]._id);
294	    const fullDocs = await store.fetchByIds(topIds);
295	    fullDocs.forEach((chunk) => assertRetrievableChunkPath(chunk, 'hydration'));
296	    const fullById = new Map(fullDocs.map(d => [String(d._id), d]));
297	
298	    return topK.map(s => ({
299	      ...fullById.get(String(allChunks[s.idx]._id)),
300	      similarity: s.sim,
301	      retrieval_mode: 'semantic',
302	    }));
303	  }
304	
305	  // --- BM25 scoring ---
306	  const bm25Index = buildBM25Index(allChunks);
307	  const queryTerms = tokenize(query);
308	  const bm25Scored = [];
309	  for (let i = 0; i < allChunks.length; i++) {
310	    const score = scoreBM25(queryTerms, i, bm25Index);
311	    if (score > 0) {
312	      bm25Scored.push({ idx: i, score, contentType: allChunks[i].content_type || 'general' });
313	    }
314	  }
315	  bm25Scored.sort((a, b) => b.score - a.score);
316	  const bm25Top = bm25Scored.slice(0, pool);
317	
318	  // --- Determine boosts ---
319	  let boosts = {};
320	  if (opts.boostType) {
321	    // Manual boost takes priority
322	    boosts[opts.boostType] = config.CONTENT_TYPE_BOOST_STRONG;
323	  } else if (mode === 'hybrid-classified') {
324	    // Auto-classify only in hybrid-classified mode
325	    boosts = classifyQuery(query);
326	  }
327	  // mode === 'hybrid' with no boostType → empty boosts → raw RRF
328	
329	  // --- RRF merge ---
330	  let merged = rrfMerge(semanticTop, bm25Top, boosts, config.RRF_K);
331	
332	  // Kind-aware modifier for code-flavored queries — penalizes doc_section
333	  // chunks that BM25 over-rewards with prose containing query terms
334	  if (isCodeFlavoredQuery(query)) {
335	    merged = merged.map(({ idx, score }) => {
336	      const kind = allChunks[idx].kind || 'window';
337	      const modifier = KIND_MODIFIER_CODE_QUERY[kind] || 1.0;
338	      return { idx, score: score * modifier };
339	    });
340	    merged.sort((a, b) => b.score - a.score);
341	  }
342	
343	  const topK = merged.slice(0, k);
344	
345	  // Hydrate winners with full text
346	  const topIds = topK.map(s => allChunks[s.idx]._id);
347	  const fullDocs = await store.fetchByIds(topIds);
348	  fullDocs.forEach((chunk) => assertRetrievableChunkPath(chunk, 'hydration'));
349	  const fullById = new Map(fullDocs.map(d => [String(d._id), d]));
350	
351	  return topK.map(s => {
352	    const full = fullById.get(String(allChunks[s.idx]._id)) || {};
353	    return {
354	      ...full,
355	      similarity: semanticScored.find(ss => ss.idx === s.idx)?.sim || 0,
356	      rrf_score: s.score,
357	      retrieval_mode: mode,
358	    };
359	  });
360	}
361	
362	// ─────────────────────────────────────────────────────────────
363	// PROMPT ASSEMBLY (unchanged from Layer 1)
364	// ─────────────────────────────────────────────────────────────
365	
366	function buildPrompt(userQuery, retrievedChunks) {
367	  const lines = [];
368	
369	  lines.push(config.MERCURY_SYSTEM_PROMPT);
370	  lines.push('');
371	  lines.push('─── RETRIEVED CODE CONTEXT ───');
372	  lines.push('');
373	
374	  retrievedChunks.forEach((chunk, idx) => {
375	    const header = `### [${idx + 1}] ${chunk.file_path}:${chunk.start_line}-${chunk.end_line}`;
376	    const subheader = `[kind: ${chunk.kind} | name: ${chunk.name} | similarity: ${(chunk.similarity || 0).toFixed(3)}]`;
377	    lines.push(header);
378	    lines.push(subheader);
379	    lines.push('```');
380	    lines.push(chunk.text);
381	    lines.push('```');
382	    lines.push('');
383	  });
384	
385	  lines.push('─── END RETRIEVED CONTEXT ───');
386	  lines.push('');
387	  lines.push('USER QUERY:');
388	  lines.push(userQuery);
389	  lines.push('');
390	  lines.push('Answer using ONLY the retrieved context above. Cite file:line for every factual claim.');
391	
392	  return lines.join('\n');
393	}
394	
395	// ─────────────────────────────────────────────────────────────
396	// MAIN ASK FUNCTION
397	// ─────────────────────────────────────────────────────────────
398	
399	async function ask(query, opts = {}) {
400	  const topK = optionalPositiveInteger(opts.topK, 'topK') ?? config.RETRIEVE_TOP_K;
401	  const maxTokens = configExactInteger(opts.maxTokens, config.SINGLE_SHOT_MAX_TOKENS, 'maxTokens');
402	  const verbose = opts.verbose !== false;
403	
404	  if (!query || typeof query !== 'string' || query.trim().length === 0) {
405	    throw new Error('ask() requires a non-empty query string');
406	  }
407	
408	  const t0 = Date.now();
409	  const store = new MongoStore();
410	  await store.connect();
411	
412	  try {
413	    const health = await store.healthCheck();
414	    if (!health.ok) throw new Error(`MongoDB health check failed: ${health.error}`);
415	    if (health.chunkCount === 0) throw new Error('No chunks in index. Run indexer.js first.');
416	
417	    if (verbose) {
418	      console.log(`[MERCURY-BRIDGE] Index contains ${health.chunkCount} chunks`);
419	      console.log(`[MERCURY-BRIDGE] Hybrid retrieval: ${config.HYBRID_ENABLED ? 'ON' : 'OFF (pure semantic)'}`);
420	      console.log('[MERCURY-BRIDGE] Embedding query...');
421	    }
422	
423	    const queryEmbedding = await embedText(query);
424	
425	    if (verbose) console.log(`[MERCURY-BRIDGE] Retrieving top ${topK} chunks...`);
426	    const topChunks = await retrieveTopK(store, queryEmbedding, topK, query);
427	
428	    if (topChunks.length === 0) {
429	      return { answer: 'No matching chunks found in the index.', chunks: [], latencyMs: Date.now() - t0 };
430	    }
431	
432	    if (verbose) {
433	      console.log('[MERCURY-BRIDGE] Top matches:');
434	      topChunks.forEach((c, idx) => {
435	        const rrfTag = c.rrf_score ? ` rrf=${c.rrf_score.toFixed(4)}` : '';
436	        console.log(`  ${idx + 1}. ${c.file_path}:${c.start_line}-${c.end_line} ` +
437	          `(${c.kind}: ${c.name}) sim=${(c.similarity || 0).toFixed(3)}${rrfTag}`);
438	      });
439	    }
440	
441	    const prompt = buildPrompt(query, topChunks);
442	
443	    if (verbose) {
444	      console.log(`[MERCURY-BRIDGE] Prompt length: ${prompt.length} chars`);
445	      console.log(`[MERCURY-BRIDGE] Calling ${config.MERCURY_LLM_PROVIDER}/${config.MERCURY_LLM_MODEL}...`);
446	    }
447	
448	    const client = createMercuryLlmClient({ systemPrompt: config.MERCURY_SYSTEM_PROMPT });
449	    await client.initialize();
450	    const answer = await client.generateResponse(prompt, maxTokens);
451	
452	    const latencyMs = Date.now() - t0;
453	    if (verbose) console.log(`[MERCURY-BRIDGE] Mercury responded in ${latencyMs}ms`);
454	
455	    return { answer, chunks: topChunks, latencyMs };
456	
457	  } finally {
458	    await store.disconnect();
459	  }
460	}
461	
462	module.exports = { ask, retrieveTopK, buildPrompt, cosineSimilarity, isCodeFlavoredQuery };
