217	  return proof?.hotPathProofs && typeof proof.hotPathProofs === 'object' && !Array.isArray(proof.hotPathProofs);
218	}
219	
220	function invalidEvidencePathFields(proof) {
221	  const invalid = [];
222	  const mercury = proof?.mercury || {};
223	  for (const fieldName of ['promptPath', 'resultPath', 'responsePath']) {
224	    const proofPath = mercury[fieldName];
225	    if (proofPath === undefined || proofPath === null || proofPath === '') continue;
226	    if (typeof proofPath !== 'string' || !proofEvidenceFileHasText(proofPath)) {
227	      invalid.push(`mercury.${fieldName}`);
228	    }
229	  }
230	
231	  const logPath = proof?.p0?.logPath;
232	  if (!proofEvidenceFileHasText(logPath)) invalid.push('p0.logPath');
233	
234	  return invalid;
235	}
236	
237	function proofMatchesCurrentDiff(fileProof, file) {
238	  return typeof fileProof?.diffFingerprint === 'string'
239	    && fileProof.diffFingerprint === currentDiffFingerprint(file);
240	}
241	
242	function addedDiffLines(files) {
243	  if (files.length === 0) return [];
244	  const diff = git(['diff', '--unified=0', 'HEAD', '--', ...files]);
245	  return diff
246	    .split('\n')
247	    .filter((line) => line.startsWith('+') && !line.startsWith('+++'))
248	    .map((line) => line.slice(1));
249	}
250	
251	function suspiciousFallbackLines(files) {
252	  return addedDiffLines(files).filter((line) => (
253	    SUSPICIOUS_ADDED_LINE.some((pattern) => pattern.test(line))
254	  ));
255	}
256	
257	function hasFallbackProof(proof, suspiciousLines) {
258	  if (suspiciousLines.length === 0) return true;
259	  const scan = proof?.fallbackDefaultScan || {};
260	  return scan.completed === true
261	    && Array.isArray(scan.reviewedAddedLines)
262	    && scan.reviewedAddedLines.length >= suspiciousLines.length
263	    && scan.noUnapprovedFallbacksOrDefaults === true;
264	}
265	
266	function proofFailuresForHotFiles(proof, hotFiles) {
267	  const failures = [];
268	  if (!proofCoversFiles(proof, hotFiles)) {
269	    failures.push('proof_changed_files_do_not_cover_current_hot_path_diff');
270	  }
271	
272	  if (!hasPerFileProofs(proof)) {
273	    const suspiciousLines = suspiciousFallbackLines(hotFiles);
274	    failures.push('missing_hot_path_file_proofs');
275	    return { failures, suspiciousLines };
276	  }
277	
278	  const allSuspiciousLines = [];
279	  for (const file of hotFiles) {
280	    const fileProof = perFileProofFor(proof, file);
281	    const suspiciousLines = suspiciousFallbackLines([file]);
282	    allSuspiciousLines.push(...suspiciousLines);
283	    if (!fileProof) {
284	      failures.push(`missing_hot_path_file_proof:${file}`);
285	      continue;
286	    }
287	    if (!proofMatchesCurrentDiff(fileProof, file)) {
288	      failures.push(`stale_hot_path_file_proof:${file}`);
289	    }
290	    if (!isAdversarialMercuryProof(fileProof) || !hasMercuryResult(fileProof)) {
291	      failures.push(`missing_adversarial_mercury_break_my_fix_proof:${file}`);
292	    }
293	    for (const fieldName of invalidEvidencePathFields(fileProof)) {
294	      failures.push(`invalid_proof_evidence_path:${file}:${fieldName}`);
295	    }
296	    if (!isP0Proof(fileProof)) failures.push(`missing_p0_gate_proof:${file}`);
297	    if (!hasFallbackProof(fileProof, suspiciousLines)) {
298	      failures.push(`unapproved_fallback_or_default_added_lines:${file}`);
299	    }
300	  }
301	
302	  return { failures, suspiciousLines: allSuspiciousLines };
303	}
304	
305	function evaluateFinishGate(files = changedFiles(), editedFiles, options = {}) {
306	  if (!Array.isArray(editedFiles)) {
307	    return {
308	      allowed: false,
309	      reason: 'missing_explicit_edit_scope',
310	      failures: ['missing_explicit_edit_scope'],
311	      hotFiles: [],
312	    };
313	  }
314	
315	  const allFiles = files;
316	  const claudeChangedFiles = editedChangedFiles(allFiles, editedFiles);
317	  const taskViolations = taskContract.changedFilesOutsideContract(claudeChangedFiles);
318	  if (taskViolations.length > 0) {
319	    return {
320	      allowed: false,
321	      reason: 'task_contract_diff_outside_write_scope',
322	      failures: ['task_contract_diff_outside_write_scope'],
323	      hotFiles: [],
324	      taskViolations,
325	    };
326	  }
327	
328	  const hotFiles = options.hotPathScope === 'edited'
329	    ? hotPathEditedChanges(allFiles, editedFiles)
330	    : hotPathChanges(allFiles);
331	  if (hotFiles.length === 0) {
332	    return { allowed: true, reason: 'no_hot_path_changes', hotFiles };
333	  }
334	
335	  const proof = Object.prototype.hasOwnProperty.call(options, 'proof')
336	    ? options.proof
337	    : loadProof();
338	  if (!proof) {
339	    return { allowed: false, reason: 'missing_hot_path_proof', hotFiles };
340	  }
341	
342	  const { failures, suspiciousLines } = proofFailuresForHotFiles(proof, hotFiles);
343	
344	  return {
345	    allowed: failures.length === 0,
346	    reason: failures.length === 0 ? 'hot_path_proof_complete' : 'hot_path_proof_incomplete',
347	    failures,
348	    hotFiles,
349	    suspiciousLines,
350	  };
351	}
352	
353	function run() {
354	  let result;
355	  try {
356	    const input = readHookInput('claude-bridge finish gate');
357	    const sessionId = editLedger.sessionIdFromHookInput(input);
358	    if (!sessionId) {
359	      throw new Error('missing session identity. Finish gate policy fails closed.');
360	    }
361	    result = evaluateFinishGate(
362	      changedFiles(),
363	      editLedger.listEditedFiles({ sessionId }),
364	      { hotPathScope: 'edited' }
365	    );
366	  } catch (error) {
367	    process.stderr.write(`BLOCKED (claude-bridge finish gate): ${error.message}\n`);
368	    process.exit(2);
369	  }
370	
371	  if (!result.allowed) {
372	    process.stderr.write(
373	      `BLOCKED (claude-bridge finish gate): ${result.reason}\n` +
374	      `Hot-path files:\n${result.hotFiles.map((file) => `  - ${file}`).join('\n')}\n` +
375	      `Failures:\n${(result.failures || [result.reason]).map((failure) => `  - ${failure}`).join('\n')}\n` +
376	      `Required proof file: .claude/session-state/hot-path-proof.json\n`
377	    );
378	    if (result.taskViolations?.length) {
379	      process.stderr.write(
380	        `Task-contract diff violations:\n${result.taskViolations.map((file) => `  - ${file}`).join('\n')}\n`
381	      );
382	    }
383	    if (result.suspiciousLines?.length) {
384	      process.stderr.write(
385	        `Suspicious added fallback/default lines:\n${result.suspiciousLines.map((line) => `  + ${line}`).join('\n')}\n`
386	      );
387	    }
388	    process.exit(2);
389	  }
390	
391	  process.exit(0);
392	}
