1	/**
2	 * @fileoverview KillSwitch - Emergency Trading Stop System
3	 *
4	 * Emergency stop mechanism that blocks ALL order execution instantly.
5	 * File-based flag ensures persistence across restarts and process crashes.
6	 *
7	 * @description
8	 * ARCHITECTURE ROLE:
9	 * KillSwitch is the ultimate safety mechanism. When activated, it blocks
10	 * every trade execution regardless of signals, patterns, or confidence.
11	 * It's the "big red button" for emergency situations.
12	 *
13	 * ACTIVATION TRIGGERS:
14	 * - Manual: Admin creates killswitch.flag file
15	 * - Automatic: RiskManager hits max drawdown
16	 * - Automatic: Circuit breaker reaches critical threshold
17	 * - Automatic: Exchange connection lost during open position
18	 *
19	 * FILE-BASED DESIGN:
20	 * Uses filesystem flag (killswitch.flag) rather than memory because:
21	 * - Persists across process crashes/restarts
22	 * - Can be activated externally (ssh, cron, monitoring)
23	 * - Multiple processes can check the same flag
24	 * - No database dependency during emergencies
25	 *
26	 * DEACTIVATION:
27	 * Requires manual intervention - delete the flag file.
28	 * This is intentional to force human review before resuming.
29	 *
30	 * @module core/KillSwitch
31	 * @requires fs
32	 *
33	 * @example
34	 * const KillSwitch = require('./core/KillSwitch');
35	 * const killSwitch = new KillSwitch();
36	 *
37	 * // Check before any trade
38	 * if (killSwitch.isKillSwitchOn()) {
39	 *   console.log('Kill switch active - trade blocked');
40	 *   return;
41	 * }
42	 *
43	 * // Activate in emergency
44	 * killSwitch.enableKillSwitch('Max drawdown reached');
45	 *
46	 * // Check status
47	 * console.log(`Kill switch: ${killSwitch.isKillSwitchOn() ? 'ON' : 'OFF'}`);
48	 */
49	
50	const fs = require('fs');
51	const path = require('path');
52	
53	const FLAG_PATH = path.join(__dirname, '../killswitch.flag');
54	const LOG_PATH = path.join(__dirname, '../logs');
55	
56	class KillSwitch {
57	    constructor() {
58	        this.lastCheckTime = null;
59	        this.isActive = null; // Cache status
60	
61	        // Ensure log directory exists
62	        if (!fs.existsSync(LOG_PATH)) {
63	            fs.mkdirSync(LOG_PATH, { recursive: true });
64	        }
65	    }
66	
67	    /**
68	     * Check if kill switch is active
69	     * @returns {boolean} true if trading should be blocked
70	     */
71	    isKillSwitchOn() {
72	        // Cache check for 1 second to avoid filesystem hammering
73	        const now = Date.now();
74	        if (this.lastCheckTime && (now - this.lastCheckTime) < 1000) {
75	            return this.isActive;
76	        }
77	
78	        this.lastCheckTime = now;
79	        this.isActive = fs.existsSync(FLAG_PATH);
80	
81	        return this.isActive;
82	    }
83	
84	    /**
85	     * Activate the kill switch - STOPS ALL TRADING
86	     * @param {string} reason - Why the kill switch was activated
87	     */
88	    enableKillSwitch(reason = 'Manual activation') {
89	        // Atomic write — emergency halt flag must never be half-written (Mercury Vector 6)
90	        const { writeJsonCompactAtomic } = require('./AtomicWrite');
91	        writeJsonCompactAtomic(FLAG_PATH, {
92	            activated: new Date().toISOString(),
93	            reason: reason,
94	            pid: process.pid
95	        });
96	
97	        // Log the activation
98	        const logEntry = `[${new Date().toISOString()}] KILL SWITCH ACTIVATED: ${reason}\n`;
99	        fs.appendFileSync(path.join(LOG_PATH, 'killswitch.log'), logEntry);
100	
101	        console.log('🔴 KILL SWITCH ACTIVATED - ALL TRADING STOPPED');
102	        console.log(`   Reason: ${reason}`);
103	
104	        this.isActive = true;
105	    }
106	
107	    /**
108	     * Deactivate the kill switch - ALLOWS TRADING
109	     */
110	    disableKillSwitch() {
111	        if (fs.existsSync(FLAG_PATH)) {
112	            // Read the flag to log deactivation
113	            let flagData = {};
114	            try {
115	                flagData = JSON.parse(fs.readFileSync(FLAG_PATH, 'utf8'));
116	            } catch (e) {
117	                flagData = { activated: 'unknown' };
118	            }
119	
120	            fs.unlinkSync(FLAG_PATH);
121	
122	            // Log the deactivation
123	            const logEntry = `[${new Date().toISOString()}] KILL SWITCH DEACTIVATED (was active since ${flagData.activated})\n`;
124	            fs.appendFileSync(path.join(LOG_PATH, 'killswitch.log'), logEntry);
125	
126	            console.log('🟢 KILL SWITCH DEACTIVATED - Trading enabled');
127	        } else {
128	            console.log('ℹ️  Kill switch was not active');
129	        }
130	
131	        this.isActive = false;
132	    }
133	
134	    /**
135	     * Get kill switch status with details
136	     */
137	    getStatus() {
138	        if (!fs.existsSync(FLAG_PATH)) {
139	            return {
140	                active: false,
141	                message: 'Kill switch is OFF - Trading enabled'
142	            };
143	        }
144	
145	        try {
146	            const flagData = JSON.parse(fs.readFileSync(FLAG_PATH, 'utf8'));
147	            const duration = Date.now() - new Date(flagData.activated).getTime();
148	            const minutes = Math.floor(duration / 60000);
149	
150	            return {
151	                active: true,
152	                activated: flagData.activated,
153	                reason: flagData.reason,
154	                duration: `${minutes} minutes`,
155	                message: `Kill switch is ON - Trading BLOCKED for ${minutes} minutes`
156	            };
157	        } catch (e) {
158	            return {
159	                active: true,
160	                message: 'Kill switch is ON - Trading BLOCKED'
161	            };
162	        }
163	    }
164	
165	    /**
166	     * Check kill switch and throw if active
167	     * Use this in critical paths
168	     */
169	    throwIfActive() {
170	        if (this.isKillSwitchOn()) {
171	            const status = this.getStatus();
172	            const error = new Error(`KILL SWITCH ACTIVE: ${status.reason || 'Trading blocked'}`);
173	            error.code = 'KILL_SWITCH_ACTIVE';
174	            throw error;
175	        }
176	    }
177	}
178	
179	// Singleton instance
180	const killSwitch = new KillSwitch();
181	
182	// Export both the class and singleton instance
183	module.exports = killSwitch;
184	module.exports.KillSwitch = KillSwitch;

1	/**
2	 * Mercury Bridge — Investigation Trace Memory
3	 * ══════════════════════════════════════════════════════════════
4	 * Captures successful ReAct investigation paths and retrieves
5	 * similar prior traces to bias future runs toward known-working
6	 * exploration strategies.
7	 *
8	 * DESIGN PRINCIPLE: This is a bias layer, not a lookup layer.
9	 * Retrieved traces are injected as HINTS, not answers. Mercury
10	 * can deviate freely. Goal: shift the opening probability
11	 * distribution toward productive paths, not replay prior runs.
12	 *
13	 * SELF-REGULATION:
14	 * 1. Dedup on capture — near-duplicates (>0.92 similarity) do
15	 *    not create new records. Instead, the better-quality run
16	 *    (fewer iterations, lower latency) replaces the worse one.
17	 * 2. Quality scoring — every trace has a quality_score computed
18	 *    from iterations and latency. Lower = better. Used for
19	 *    replacement decisions and eviction ordering.
20	 * 3. Usage tracking — usage_count increments when a trace is
21	 *    actually retrieved and injected as a hint. Proven-useful
22	 *    traces are protected from eviction.
23	 * 4. Eviction — scheduled cleanup drops unused + old + low-quality
24	 *    traces when the collection exceeds the configured cap.
25	 *
26	 * Storage: configured mongo collection (separate
27	 * from the `chunks` collection used for code/doc retrieval).
28	 *
29	 * CAPTURE CRITERIA: Only successful runs (termination ===
30	 * 'answer_given') are captured. Manual capture mode also requires
31	 * an explicit capture request. Failed runs do not teach.
32	 */
33	
34	'use strict';
35	
36	const { embedText } = require('./indexer');
37	const config = require('./config');
38	
39	const TRACE_COLLECTION = config.TRACE_COLLECTION;
40	const CURRENT_FIX_QUERY_PATTERN = /\b(break my fix|current fix|current change|staged fix|staged change|uncommitted|working tree|latest committed|last commit)\b/i;
41	
42	// ─── Cosine similarity ────────────────────────────────────────
43	
44	function cosineSimilarity(a, b) {
45	  if (!a || !b || a.length !== b.length) return 0;
46	  let dot = 0, normA = 0, normB = 0;
47	  for (let i = 0; i < a.length; i++) {
48	    dot += a[i] * b[i];
49	    normA += a[i] * a[i];
50	    normB += b[i] * b[i];
51	  }
52	  const denom = Math.sqrt(normA) * Math.sqrt(normB);
53	  return denom === 0 ? 0 : dot / denom;
54	}
55	
56	// ─── Quality scoring ──────────────────────────────────────────
57	// Lower is better. Dominated by iteration count (each iteration
58	// is expensive in tool calls + model time), latency is a tiebreaker.
59	
60	function computeQualityScore({ iterations, latencyMs, latency_ms }) {
61	  const latency = latencyMs || latency_ms || 0;
62	  return iterations * 10 + (latency / 1000);
63	}
64	
65	function hasToolCall(toolCallSequence, toolName) {
66	  return (toolCallSequence || []).some((toolCall) => toolCall && toolCall.name === toolName);
67	}
68	
69	function shouldCaptureTrace({ query, toolCallSequence, metadata, captureRequested = false }) {
70	  if (!metadata || metadata.termination !== 'answer_given') {
71	    return { capture: false, reason: 'termination_not_successful' };
72	  }
73	
74	  if (config.TRACE_CAPTURE_MODE === 'manual' && captureRequested !== true) {
75	    return { capture: false, reason: 'manual_capture_not_requested' };
76	  }
77	
78	  if (CURRENT_FIX_QUERY_PATTERN.test(query || '') && !hasToolCall(toolCallSequence, 'git_diff')) {
79	    return { capture: false, reason: 'current_fix_without_git_diff' };
80	  }
81	
82	  return { capture: true };
83	}
84	
85	// ─── Capture ──────────────────────────────────────────────────
86	
87	/**
88	 * Capture a successful investigation trace with dedup + quality replacement.
89	 *
90	 * Behavior:
91	 * 1. Embed the query.
92	 * 2. Scan existing traces for any with similarity >= DEDUP_THRESHOLD (0.92).
93	 * 3. If a near-duplicate exists:
94	 *    - If new trace has better quality, REPLACE the existing one.
95	 *    - If existing trace has better or equal quality, SKIP capture.
96	 * 4. If no near-duplicate, INSERT new trace.
97	 */
98	async function captureTrace({ store, query, toolCallSequence, finalAnswer, metadata, captureRequested = false }) {
99	  const captureGate = shouldCaptureTrace({ query, toolCallSequence, finalAnswer, metadata, captureRequested });
100	  if (!captureGate.capture) {
101	    return { captured: false, reason: captureGate.reason };
102	  }
103	
104	  try {
105	    const queryEmbedding = await embedText(query);
106	    const traceCollection = store.db.collection(TRACE_COLLECTION);
107	    const newQuality = computeQualityScore(metadata);
108	
109	    // Scan for near-duplicates
110	    const allTraces = await traceCollection.find({}).toArray();
111	    let nearDuplicate = null;
112	    for (const existing of allTraces) {
113	      const sim = cosineSimilarity(queryEmbedding, existing.query_embedding);
114	      if (sim >= config.TRACE_DEDUP_THRESHOLD) {
115	        if (!nearDuplicate || sim > nearDuplicate.similarity) {
116	          nearDuplicate = { existing, similarity: sim };
117	        }
118	      }
119	    }
120	
121	    const traceDoc = {
122	      query,
123	      query_embedding: queryEmbedding,
124	      tool_call_sequence: toolCallSequence.map(tc => ({
125	        name: tc.name,
126	        args: tc.args,
127	        result_summary: (tc.result_summary || '').slice(0, 500),
128	      })),
129	      final_answer_excerpt: (finalAnswer || '').slice(0, 2000),
130	      iterations: metadata.iterations,
131	      latency_ms: metadata.latencyMs,
132	      quality_score: newQuality,
133	      usage_count: 0,
134	      created_at: new Date(),
135	      last_used_at: null,
136	      updated_at: new Date(),
137	    };
138	
139	    if (nearDuplicate) {
140	      const existingQuality = nearDuplicate.existing.quality_score;
141	      if (newQuality < existingQuality) {
142	        // New trace is higher quality — replace, but preserve usage_count
143	        traceDoc.usage_count = nearDuplicate.existing.usage_count || 0;
144	        traceDoc.created_at = nearDuplicate.existing.created_at || new Date();
145	        await traceCollection.replaceOne(
146	          { _id: nearDuplicate.existing._id },
147	          traceDoc
148	        );
149	        return {
150	          captured: true,
151	          action: 'replaced',
152	          similarity: nearDuplicate.similarity,
153	          old_quality: existingQuality,
154	          new_quality: newQuality,
155	        };
156	      } else {
157	        return {
158	          captured: false,
159	          action: 'skipped_worse_quality',
160	          similarity: nearDuplicate.similarity,
161	          existing_quality: existingQuality,
162	          new_quality: newQuality,
163	        };
164	      }
165	    }
166	
167	    // No near-duplicate — insert new
168	    await traceCollection.insertOne(traceDoc);
169	    return { captured: true, action: 'inserted', quality: newQuality };
170	
171	  } catch (err) {
172	    console.error(`[TRACE-MEMORY] Capture failed: ${err.message}`);
173	    return { captured: false, reason: 'capture_error', error: err.message };
174	  }
175	}
176	
177	// ─── Retrieve ─────────────────────────────────────────────────
178	
179	/**
180	 * Retrieve the most similar prior trace for a query, above the
181	 * injection threshold. Returns null if nothing qualifies.
182	 */
183	async function retrieveSimilarTrace({ store, query, threshold }) {
184	  const minSim = threshold != null ? threshold : config.TRACE_INJECT_THRESHOLD;
185	
186	  try {
187	    const traceCollection = store.db.collection(TRACE_COLLECTION);
188	    const allTraces = await traceCollection.find({}).toArray();
189	
190	    if (allTraces.length === 0) return null;
191	
192	    const queryEmbedding = await embedText(query);
193	
194	    let best = null;
195	    for (const trace of allTraces) {
196	      if (!trace.query_embedding) continue;
197	      const sim = cosineSimilarity(queryEmbedding, trace.query_embedding);
198	      if (!best || sim > best.similarity) {
199	        best = { trace, similarity: sim };
200	      }
201	    }
202	
203	    if (best && best.similarity >= minSim) {
204	      return best;
205	    }
206	    return null;
207	  } catch (err) {
208	    console.error(`[TRACE-MEMORY] Retrieve failed: ${err.message}`);
209	    return null;
210	  }
211	}
212	
213	/**
214	 * Mark a trace as used (increment usage_count, update last_used_at).
215	 * Called AFTER a trace has actually been injected into starter context.
216	 */
217	async function markTraceUsed({ store, traceId }) {
218	  try {
219	    const traceCollection = store.db.collection(TRACE_COLLECTION);
220	    await traceCollection.updateOne(
221	      { _id: traceId },
222	      {
223	        $inc: { usage_count: 1 },
224	        $set: { last_used_at: new Date() },
225	      }
226	    );
227	  } catch (err) {
228	    console.error(`[TRACE-MEMORY] Usage update failed: ${err.message}`);
229	  }
230	}
231	
232	// ─── Format hint ──────────────────────────────────────────────
233	
234	function formatTraceAsHint(traceResult) {
235	  if (!traceResult) return null;
236	
237	  const { trace, similarity } = traceResult;
238	  const lines = [];
239	  lines.push('─── PRIOR INVESTIGATION HINT ───');
240	  lines.push(`A similar query was successfully answered previously (similarity: ${similarity.toFixed(2)}).`);
241	  lines.push(`Prior query: "${trace.query}"`);
242	  lines.push(`It was solved in ${trace.iterations} iterations using this tool sequence:`);
243	  lines.push('');
244	
245	  trace.tool_call_sequence.forEach((tc, idx) => {
246	    const argsStr = typeof tc.args === 'string' ? tc.args : JSON.stringify(tc.args);
247	    lines.push(`  ${idx + 1}. ${tc.name}(${argsStr.slice(0, 150)}${argsStr.length > 150 ? '...' : ''})`);
