1	#!/usr/bin/env node
2	/**
3	 * Mercury Bridge — CLI Entry
4	 * ══════════════════════════════════════════════════════════════
5	 * Ask Mercury questions about the OGZPrime codebase with either:
6	 *   (default) single-shot RAG — fast but can be fooled by docs
7	 *   --agentic  ReAct loop with tool access — Mercury iteratively
8	 *              greps the repo and opens files until it has ground truth
9	 *
10	 * Usage:
11	 *   node trai_brain/mercury-bridge/ask.js "How does MPM handle BE scale-out?"
12	 *   node trai_brain/mercury-bridge/ask.js --agentic "Find the partial-close contract bug"
13	 *
14	 * Flags:
15	 *   --agentic              Enable ReAct loop
16	 *   --top-k=N              Retrieve N starter-context chunks
17	 *   --max-iterations=N     Agentic mode only: max tool-call iterations
18	 *   --max-tokens=N         Mercury max tokens per turn
19	 *   --quiet                Suppress progress logs
20	 *   --show-chunks          Print retrieved chunk text (not just filenames)
21	 *   --show-history         Agentic mode only: print the full tool-call trace
22	 *   --adversarial-review   Agentic mode only: ask Fable to attack Mercury's answer
23	 *   --consensus            Agentic mode only: legacy alias for Fable review
24	 *   --architecture         Agentic mode only: longform architecture review framing
25	 *   --planning             Agentic mode only: implementation planning/design framing
26	 *   --check-providers      Warm up Mercury and Fable clients, then exit
27	 */
28	
29	'use strict';
30	
