187	function optionalPositiveInteger(value, name) {
188	  if (value == null) return null;
189	  if (!Number.isInteger(value) || value < 1) {
190	    throw new Error(`${name} must be a positive integer`);
191	  }
192	  return value;
193	}
194	
195	function optionalNonNegativeInteger(value, name) {
196	  if (value == null) return null;
197	  if (!Number.isInteger(value) || value < 0) {
198	    throw new Error(`${name} must be a non-negative integer`);
199	  }
200	  return value;
201	}
202	
203	function configExactInteger(value, configuredValue, name) {
204	  if (value == null) return configuredValue;
205	  const parsed = optionalPositiveInteger(value, name);
206	  if (parsed !== configuredValue) {
207	    throw new Error(`${name} must match mercury.config.json value ${configuredValue}`);
208	  }
209	  return configuredValue;
210	}
