279	function normalizeRepoRelativePath(repoRoot, relPath) {
280	  if (!relPath || typeof relPath !== 'string') return null;
281	  if (relPath.startsWith('/') || relPath.split('/').includes('..')) return null;
282	  const absPath = path.resolve(repoRoot, relPath);
283	  const normalizedRoot = path.resolve(repoRoot);
284	  if (absPath !== normalizedRoot && !absPath.startsWith(`${normalizedRoot}${path.sep}`)) {
285	    return null;
286	  }
287	  return path.relative(normalizedRoot, absPath).replace(/\\/g, '/');
288	}
