290	function isSerenaSourcePath(relPath) {
291	  return typeof relPath === 'string'
292	    && relPath.endsWith('.js')
293	    && !relPath.endsWith('.bak')
294	    && !config.isPathIgnoredByMercury(relPath);
295	}
