297	async function buildCurrentChangeBlastRadius({
298	  repoRoot = config.REPO_ROOT,
299	  changedFiles = null,
300	  currentChangedFilesFn = currentChangedFiles,
301	  getBlastRadiusFn = getBlastRadius,
302	  formatForMercuryFn = formatForMercury,
303	} = {}) {
304	  let candidates;
305	  try {
306	    candidates = changedFiles || currentChangedFilesFn(repoRoot);
307	  } catch (err) {
308	    return {
309	      text: null,
310	      meta: [],
311	      errors: [
312	        {
313	          file: '<current_changes>',
314	          error: err.message,
315	        },
316	      ],
317	      source: 'current_changes',
318	    };
319	  }
320	  const targetFiles = [];
321	  for (const candidate of candidates) {
322	    const relPath = normalizeRepoRelativePath(repoRoot, candidate);
323	    if (!relPath || !isSerenaSourcePath(relPath)) continue;
324	    if (!fs.existsSync(path.join(repoRoot, relPath))) continue;
325	    targetFiles.push(relPath);
326	  }
327	
328	  if (targetFiles.length === 0) {
329	    return {
330	      text: null,
331	      meta: [],
332	      errors: [],
333	      source: 'current_changes',
334	    };
335	  }
336	
337	  const sections = [];
338	  const meta = [];
339	  const errors = [];
340	  for (const targetFile of targetFiles) {
341	    let blastRadius;
342	    try {
343	      blastRadius = await getBlastRadiusFn(targetFile);
344	    } catch (err) {
345	      errors.push({
346	        file: targetFile,
347	        error: err.message,
348	      });
349	      continue;
350	    }
351	    let formatted;
352	    try {
353	      formatted = formatForMercuryFn(blastRadius);
354	    } catch (err) {
355	      errors.push({
356	        file: targetFile,
357	        error: `format failed: ${err.message}`,
358	      });
359	      continue;
360	    }
361	    meta.push({
362	      file: targetFile,
363	      callerCount: blastRadius.callerCount,
364	      riskLevel: blastRadius.riskLevel,
365	      latencyMs: blastRadius.latencyMs,
366	    });
367	    sections.push(`## ${targetFile}\n${formatted}`);
368	  }
369	
370	  return {
371	    text: sections.length > 0 ? sections.join('\n\n') : null,
372	    meta,
373	    errors,
374	    source: 'current_changes',
375	  };
376	}
