382	async function runAgentic(query, opts) {
383	  const startedAt = new Date();
384	  const verbose = !opts.quiet;
385	  const maxIterations = configExactInteger(opts.maxIterations, config.AGENTIC_MAX_ITERATIONS, '--max-iterations');
386	  const maxTokens = configExactInteger(opts.maxTokens, config.AGENTIC_MAX_TOKENS, '--max-tokens');
387	  const reviewIntent = opts.reviewIntent || 'adversarial';
388	  const mercuryQuery = buildMercuryIntentPrompt(query, reviewIntent);
389	
390	  // Route the query unless caller has overridden
391	  const route = routeQuery(query);
392	  const mode = opts.retrievalMode || route.mode;
393	  const boostType = opts.boostType != null ? opts.boostType : route.boostType;
394	  const explicitTopK = optionalNonNegativeInteger(opts.topK, '--top-k');
395	
396	  // Starter context policy: respect --top-k if caller set it, otherwise route decides
397	  let topK;
398	  if (explicitTopK != null) {
399	    topK = explicitTopK;
400	  } else if (route.starterContextPolicy === 'skip') {
401	    topK = 0;
402	  } else {
403	    topK = config.RETRIEVE_TOP_K;
404	  }
405	
406	  // 1. Retrieve starter context from the existing indexed corpus
407	  const store = new MongoStore();
408	  let storeConnected = false;
409	  let autoBlastRadius = null;
410	
411	  try {
412	    await store.connect();
413	    storeConnected = true;
414	
415	    const health = await store.healthCheck();
416	    if (!health.ok) {
417	      throw new Error(`MongoDB health check failed: ${health.error}`);
418	    }
419	    if (health.chunkCount === 0) {
420	      throw new Error('No chunks in index. Run indexer.js first.');
421	    }
422	
423	    if (verbose) {
424	      console.log(`[MERCURY-BRIDGE] Index contains ${health.chunkCount} chunks`);
425	      console.log(`[MERCURY-BRIDGE] Query router: type=${route.queryType} mode=${mode} boost=${boostType || 'none'} top-k=${topK}`);
426	      console.log(`[MERCURY-BRIDGE] Rationale: ${route.rationale}`);
427	    }
428	
429	    let starterContext = [];
430	    if (topK > 0) {
431	      if (verbose) console.log('[MERCURY-BRIDGE] Embedding query for starter context...');
432	      const queryEmbedding = await embedText(query);
433	      starterContext = await retrieveTopK(store, queryEmbedding, topK, query, {
434	        retrievalMode: mode,
435	        boostType: boostType,
436	      });
437	    } else {
438	      if (verbose) console.log('[MERCURY-BRIDGE] Starter context: skipped (router policy=skip)');
439	    }
440	
441	    if (verbose) {
442	      console.log(`[MERCURY-BRIDGE] Starter context: ${starterContext.length} chunks`);
443	      starterContext.forEach((c, idx) => {
444	        console.log(`  ${idx + 1}. ${c.file_path}:${c.start_line}-${c.end_line} ` +
445	          `(${c.kind}: ${c.name || 'unnamed'}) sim=${c.similarity.toFixed(3)}`);
446	      });
447	    }
448	
449	    // 2. Investigation trace memory — retrieve prior hint if available
450	    let traceHintText = null;
451	    let traceUsed = null;
452	    if (config.TRACE_MEMORY_ENABLED) {
453	      await ensureTraceIndexes(store);
454	      await evictStaleTraces({ store, verbose });
455	
456	      const traceResult = await retrieveSimilarTrace({ store, query });
457	      if (traceResult) {
458	        traceHintText = formatTraceAsHint(traceResult);
459	        traceUsed = traceResult.trace;
460	        if (verbose) {
461	          console.log(`[MERCURY-BRIDGE] Prior trace hint found (similarity: ${traceResult.similarity.toFixed(2)}, ${traceResult.trace.iterations} iters, used ${traceResult.trace.usage_count}x)`);
462	        }
463	      } else if (verbose) {
464	        console.log('[MERCURY-BRIDGE] No similar prior trace found');
