493	          autoBlastRadius.meta.forEach((meta) => {
494	            console.log(`  ${meta.file}: ${meta.callerCount} caller(s), risk=${meta.riskLevel}, ${meta.latencyMs}ms`);
495	          });
496	        } else {
497	          console.log('[MERCURY-BRIDGE] Serena current-change blast radius: no changed JS files to scan');
498	        }
499	        if (autoBlastRadius.errors.length > 0) {
500	          console.log(`[MERCURY-BRIDGE] Serena current-change blast radius unavailable for ${autoBlastRadius.errors.length} file(s)`);
