540	          blocking: false,
541	        },
542	      };
543	      result.consensus = result.adversarialReview;
544	      if (verbose) {
545	        console.log(`[MERCURY-BRIDGE] Fable ${reviewMode} skipped: Mercury tool failure makes verdict inconclusive_toolfail`);
