1	/**
2	 * Mercury Bridge — Query Router (Layer 1)
3	 * ══════════════════════════════════════════════════════════════
4	 * Inspects the incoming query and decides the full retrieval
5	 * strategy: mode, content_type boost, starter-context policy,
6	 * iteration preference.
7	 *
8	 * This is the "traffic cop" that sits in front of the retrieval
9	 * engine. It does not score chunks or talk to MongoDB — it reads
10	 * the query text, applies heuristic rules, and returns a strategy
11	 * object that downstream components honor.
12	 *
13	 * Design principle: cheap, explainable, inspectable. No LLM calls,
14	 * no embeddings, just pattern matching and simple rules. When the
15	 * rules are wrong, the caller can override via CLI flags.
16	 */
17	
18	'use strict';
19	
20	// ─── Pattern definitions ──────────────────────────────────────
21	
22	const HISTORICAL_PATTERNS = [
23	  /\b(have we|has there( ever)? been|did we ever|was there a|has this)\b/i,
24	  /\b(what fixed|what was the fix|how was .+ fixed|resolved|patched)\b/i,
25	  /\b(previous|prior|earlier) (bug|issue|error|problem)\b/i,
26	  /\b(history|past|before) (of|on|with)\b/i,
27	];
28	
29	const ARCHITECTURAL_PATTERNS = [
30	  /\b(how does|how do|how is) .+ (work|function|operate)\b/i,
31	  /\b(architecture|design|structure|layout) of\b/i,
32	  /\b(relationship|contract|interface) between\b/i,
33	  /\b(what is the purpose of|what does .+ do)\b/i,
34	  /\b(flow|pipeline|sequence) (of|for)\b/i,
35	];
36	
37	const LANDMINE_PATTERNS = [
38	  /\b(should i avoid|what to avoid|pitfall|gotcha)\b/i,
39	  /\b(rules?|guidelines?|guardrails?|constraints?)\b/i,
40	  /\b(never|don'?t|must not|cannot)\b.*\b(use|do|call|modify|touch)\b/i,
41	  /\b(known (issues?|landmines?|problems?))\b/i,
42	];
43	
44	const CONTRACT_BUG_PATTERNS = [
45	  /\b(contract (mismatch|violation|break))\b/i,
46	  /\b(disagree|mismatch|inconsistent)\b/i,
47	  /\bone side .+ other side\b/i,
48	  /\b(expects|expected) .+ (but|yet|while)\b/i,
49	];
50	
51	const RECENT_CHANGE_PATTERNS = [
52	  /\b(recent|recently|latest|last (week|month|session|day))\b/i,
53	  /\b(what changed|what'?s new|new in|added in)\b/i,
54	  /\b(changelog|release notes|commit history)\b/i,
55	];
56	
57	const PROPOSAL_PATTERNS = [
58	  /\b(propose|proposal|planned|plan for|intend|roadmap)\b/i,
59	  /\b(future|upcoming) (work|feature|change|refactor)\b/i,
60	  /\b(should we|ought to|supposed to) (build|add|implement)\b/i,
61	];
62	
63	function hasIdentifiers(query) {
64	  if (!query || typeof query !== 'string') return false;
65	  if (/[a-z][A-Z]/.test(query)) return true;
66	  if (/[a-zA-Z]_[a-zA-Z]/.test(query)) return true;
67	  if (/\b\w+\.\w+\b/.test(query)) return true;
68	  if (/\.(js|ts|mjs|cjs|json|jsonl|md|py|sh)\b/i.test(query)) return true;
69	  return false;
70	}
71	
72	function matchesAny(query, patterns) {
73	  return patterns.some((re) => re.test(query));
74	}
75	
76	// ─── Router ───────────────────────────────────────────────────
77	
78	/**
79	 * Classify a query and return a full retrieval strategy.
80	 *
81	 * @param {string} query
82	 * @returns {{
83	 *   queryType: string,
84	 *   mode: 'semantic' | 'hybrid' | 'hybrid-classified',
85	 *   boostType: string | null,
86	 *   starterContextPolicy: 'prefer' | 'mixed' | 'skip',
87	 *   rationale: string
88	 * }}
89	 */
90	function routeQuery(query) {
91	  if (!query || typeof query !== 'string') {
92	    return {
93	      queryType: 'general',
94	      mode: 'hybrid',
95	      boostType: null,
96	      starterContextPolicy: 'mixed',
97	      rationale: 'empty or invalid query, fallback to hybrid/mixed',
98	    };
99	  }
100	
101	  if (matchesAny(query, CONTRACT_BUG_PATTERNS)) {
102	    return {
103	      queryType: 'contract_bug',
104	      mode: 'hybrid',
105	      boostType: null,
106	      starterContextPolicy: 'mixed',
107	      rationale: 'contract bug pattern detected; use indexed starter context plus agentic tools',
108	    };
109	  }
110	
111	  if (matchesAny(query, HISTORICAL_PATTERNS)) {
112	    return {
113	      queryType: 'historical',
114	      mode: 'hybrid-classified',
115	      boostType: null,
116	      starterContextPolicy: 'prefer',
117	      rationale: 'historical/bug-retrospective pattern detected; prefer starter context from canonical docs',
118	    };
119	  }
120	
121	  if (matchesAny(query, RECENT_CHANGE_PATTERNS)) {
122	    return {
123	      queryType: 'recent_change',
124	      mode: 'hybrid-classified',
125	      boostType: 'recent_changes',
126	      starterContextPolicy: 'prefer',
127	      rationale: 'recent-change pattern detected; boost recent_changes and changelog',
128	    };
129	  }
130	
131	  if (matchesAny(query, LANDMINE_PATTERNS)) {
132	    return {
133	      queryType: 'landmine',
134	      mode: 'hybrid-classified',
135	      boostType: 'landmine',
136	      starterContextPolicy: 'prefer',
137	      rationale: 'landmine/rules pattern detected; boost landmine and guardrails',
138	    };
139	  }
140	
141	  if (matchesAny(query, PROPOSAL_PATTERNS)) {
142	    return {
143	      queryType: 'proposal',
144	      mode: 'hybrid-classified',
145	      boostType: 'proposal',
146	      starterContextPolicy: 'prefer',
147	      rationale: 'proposal/planning pattern detected; boost proposal content_type',
148	    };
149	  }
150	
151	  if (matchesAny(query, ARCHITECTURAL_PATTERNS)) {
152	    return {
153	      queryType: 'architectural',
154	      mode: 'hybrid',
155	      boostType: 'project_context',
156	      starterContextPolicy: 'mixed',
157	      rationale: 'architectural question detected; boost project_context, mixed starter+tools',
158	    };
159	  }
160	
161	  if (hasIdentifiers(query)) {
162	    return {
163	      queryType: 'identifier',
164	      mode: 'hybrid',
165	      boostType: null,
166	      starterContextPolicy: 'mixed',
167	      rationale: 'code-flavored query with identifiers; kind modifier handles this in Layer 2',
168	    };
169	  }
170	
171	  return {
172	    queryType: 'general',
173	    mode: 'hybrid',
174	    boostType: null,
175	    starterContextPolicy: 'mixed',
176	    rationale: 'no specific pattern matched; default hybrid with mixed starter policy',
177	  };
178	}
179	
180	module.exports = {
181	  routeQuery,
182	  hasIdentifiers,
183	  matchesAny,
184	  HISTORICAL_PATTERNS,
185	  ARCHITECTURAL_PATTERNS,
186	  LANDMINE_PATTERNS,
187	  CONTRACT_BUG_PATTERNS,
188	  RECENT_CHANGE_PATTERNS,
189	  PROPOSAL_PATTERNS,
190	};
