7	function execFileAsync(command, args, options = {}) {
8	  return new Promise((resolve, reject) => {
9	    execFile(command, args, options, (error, stdout, stderr) => {
10	      if (error) {
11	        error.stdout = stdout;
12	        error.stderr = stderr;
13	        reject(error);
14	        return;
15	      }
16	      resolve({ stdout, stderr });
17	    });
18	  });
