25	function extractAnswerFromClaudeCodeFrames(frames) {
26	  const resultFrame = [...frames].reverse().find(frame => frame && frame.type === 'result' && typeof frame.result === 'string');
27	  if (resultFrame) return resultFrame.result;
28	
29	  const assistantFrame = [...frames].reverse().find(frame => frame && frame.type === 'assistant' && frame.message);
30	  const content = assistantFrame && assistantFrame.message && assistantFrame.message.content;
31	  if (typeof content === 'string') return content.trim();
32	  if (Array.isArray(content)) {
33	    return content
34	      .filter(part => part && part.type === 'text')
35	      .map(part => part.text || '')
36	      .join('\n')
37	      .trim();
38	  }
39	
40	  return null;
41	}
