43	function splitJsonValuesFromLine(line) {
44	  const values = [];
45	  let start = -1;
46	  let depth = 0;
47	  let quote = null;
48	  let escaping = false;
49	
50	  for (let index = 0; index < line.length; index += 1) {
51	    const char = line[index];
52	
53	    if (quote) {
54	      if (escaping) {
55	        escaping = false;
56	      } else if (char === '\\') {
57	        escaping = true;
58	      } else if (char === quote) {
59	        quote = null;
60	      }
61	      continue;
62	    }
63	
64	    if (char === '"' || char === "'") {
65	      quote = char;
66	      continue;
67	    }
68	
69	    if (char === '{' || char === '[') {
70	      if (depth === 0) start = index;
71	      depth += 1;
72	      continue;
73	    }
74	
75	    if ((char === '}' || char === ']') && depth > 0) {
76	      depth -= 1;
77	      if (depth === 0 && start !== -1) {
78	        values.push(line.slice(start, index + 1));
79	        start = -1;
80	      }
81	    }
82	  }
83	
84	  return values;
85	}
