96	  /**
97	   * Bulk insert — used when doing a full reindex.
98	   * Caller is responsible for clearing the collection first via clearAll().
99	   */
100	  async bulkInsert(chunks) {
101	    if (chunks.length === 0) return { inserted: 0 };
102	    this.assertActiveEmbedChunks(chunks);
103	    // Chunk the inserts to avoid MongoDB's 16MB document size limit on batch ops
104	    const BATCH_SIZE = 500;
