182	  /**
183	   * Get collection stats for observability.
184	   */
185	  async getStats() {
186	    const chunkCount = await this.chunks.countDocuments(activeEmbedQuery());
187	    const latestRun = await this.stats
188	      .find(activeEmbedQuery())
189	      .sort({ run_at: -1 })
