200	   * Health check — verify connection + collection accessible.
201	   */
202	  async healthCheck() {
203	    try {
204	      await this.db.command({ ping: 1 });
205	      const count = await this.chunks.countDocuments();
206	      const activeCount = await this.chunks.countDocuments(activeEmbedQuery());
207	      return {
208	        ok: true,
