140	/**
141	 * Recursively walk a directory, yielding file paths that should be indexed.
142	 * Respects SKIP_DIRS, SKIP_FILE_EXTENSIONS, SKIP_FILE_PATTERNS, and MAX_FILE_BYTES.
143	 */
144	function walkRepo(rootDir) {
145	  const files = [];
146	
147	  function walk(dir) {
148	    let entries;
149	    try {
150	      entries = fs.readdirSync(dir, { withFileTypes: true });
151	    } catch (err) {
152	      console.warn(`[walker] Cannot read ${dir}: ${err.message}`);
153	      return;
154	    }
155	
156	    for (const entry of entries) {
157	      const fullPath = path.join(dir, entry.name);
158	
159	      if (entry.isDirectory()) {
160	        if (config.SKIP_DIRS.has(entry.name)) continue;
161	        if (entry.name.startsWith('.')) continue;  // skip hidden dirs
162	        if (!shouldDescendDirectory(rootDir, fullPath)) continue;
163	        walk(fullPath);
164	        continue;
165	      }
166	
167	      if (!entry.isFile()) continue;
168	      if (!isIndexEligiblePath(rootDir, fullPath)) continue;
169	
170	      const ext = path.extname(entry.name).toLowerCase();
171	      if (config.SKIP_FILE_EXTENSIONS.has(ext)) continue;
172	      if (!config.INDEX_FILE_EXTENSIONS.has(ext)) continue;
173	
174	      if (config.SKIP_FILE_PATTERNS.some((pat) => pat.test(entry.name))) continue;
175	
176	      // Size check
177	      let stat;
178	      try {
179	        stat = fs.statSync(fullPath);
180	      } catch {
181	        continue;
182	      }
183	      if (stat.size > config.MAX_FILE_BYTES) {
184	        console.warn(`[walker] Skipping ${fullPath} (${stat.size} bytes > ${config.MAX_FILE_BYTES})`);
185	        continue;
186	      }
187	
188	      files.push(fullPath);
189	    }
190	  }
191	
192	  walk(rootDir);
193	  return files;
194	}
