200	/**
201	 * Chunk JavaScript/TypeScript source by function, class, and method.
202	 * Uses regex to find definitions, then brace-counting to find the body end.
203	 * Falls back to sliding window for files where no definitions matched.
204	 *
205	 * KNOWN LIMITATION (documented, not a bug): misses functions defined inside
206	 * object literals, dynamically-named methods, and unusual arrow patterns.
207	 * Fallback window catches whatever regex misses.
208	 */
209	function chunkJavaScript(text, filePath) {
210	  const chunks = [];
211	  const lines = text.split('\n');
212	
213	  // Patterns that indicate the start of a function/method definition.
214	  // NOTE: NO class pattern — class containers would consume the entire class body.
215	  // Methods inside classes are picked up individually by the method pattern.
216	  // Each pattern captures the name in a known group for metadata.
217	  const patterns = [
218	    // function name(...)  /  async function name(...)
219	    { re: /^(\s*)(?:async\s+)?function\s+(\w+)\s*\(/, kind: 'function', nameGroup: 2 },
220	    // const name = (...) =>  /  const name = async (...) =>
221	    { re: /^(\s*)(?:const|let|var)\s+(\w+)\s*=\s*(?:async\s*)?\([^)]*\)\s*=>/, kind: 'function', nameGroup: 2 },
222	    // const name = function(...)
223	    { re: /^(\s*)(?:const|let|var)\s+(\w+)\s*=\s*(?:async\s*)?function\s*\(/, kind: 'function', nameGroup: 2 },
224	    // module.exports.name = function(...) / exports.name = function(...)
225	    { re: /^(\s*)(?:module\.)?exports\.(\w+)\s*=\s*(?:async\s*)?function\s*\(/, kind: 'function', nameGroup: 2 },
226	    // class methods:  name(...) {   or   async name(...) {
227	    // Loose; filtered with KEYWORD_BLACKLIST below.
228	    { re: /^(\s+)(?:async\s+)?(\w+)\s*\([^)]*\)\s*\{/, kind: 'method', nameGroup: 2 },
229	    // static methods
230	    { re: /^(\s+)static\s+(?:async\s+)?(\w+)\s*\([^)]*\)\s*\{/, kind: 'method', nameGroup: 2 },
231	  ];
232	
233	  // Reserved words that look like methods to the loose regex but aren't
234	  const KEYWORD_BLACKLIST = new Set([
235	    'if', 'else', 'for', 'while', 'switch', 'catch', 'try', 'do',
236	    'return', 'function', 'class', 'const', 'let', 'var', 'new',
237	    'typeof', 'instanceof', 'throw', 'await', 'yield',
238	  ]);
239	
240	  let i = 0;
241	  while (i < lines.length) {
242	    const line = lines[i];
243	
244	    let matched = null;
245	    for (const { re, kind, nameGroup } of patterns) {
246	      const m = line.match(re);
247	      if (!m) continue;
248	
249	      const name = m[nameGroup];
250	      if (!name || KEYWORD_BLACKLIST.has(name)) continue;
251	
252	      matched = { kind, name, startLine: i + 1 };
253	      break;
254	    }
255	
256	    if (!matched) {
257	      i++;
258	      continue;
259	    }
260	
261	    // Find the matching brace to determine the end line
262	    const endLine = findMatchingBrace(lines, i);
263	    if (endLine === -1) {
264	      i++;
265	      continue;
266	    }
267	
268	    const chunkText = lines.slice(i, endLine + 1).join('\n');
269	
270	    // Skip tiny chunks (less than 2 lines of body)
271	    if (chunkText.split('\n').length < 3) {
272	      i = endLine + 1;
273	      continue;
274	    }
275	
276	    // Guard against chunks larger than our max
277	    if (chunkText.length > config.MAX_CHUNK_CHARS) {
278	      // Split this oversized chunk into sliding windows
279	      const windows = slidingWindow(chunkText, config.CHUNK_WINDOW_SIZE, config.CHUNK_WINDOW_OVERLAP);
280	      windows.forEach((winText, idx) => {
281	        chunks.push({
282	          kind: matched.kind,
283	          name: `${matched.name}#part${idx + 1}`,
284	          start_line: matched.startLine,
285	          end_line: endLine + 1,
286	          text: winText,
287	        });
288	      });
289	    } else {
290	      chunks.push({
291	        kind: matched.kind,
292	        name: matched.name,
293	        start_line: matched.startLine,
294	        end_line: endLine + 1,
295	        text: chunkText,
296	      });
297	    }
298	
299	    i = endLine + 1;
300	  }
301	
302	  // Fallback: if no matched chunks, use sliding window on the whole file
303	  if (chunks.length === 0) {
304	    const windows = slidingWindow(text, config.CHUNK_WINDOW_SIZE, config.CHUNK_WINDOW_OVERLAP);
305	    windows.forEach((winText, idx) => {
306	      // Estimate line range for the window
307	      const startChar = idx * (config.CHUNK_WINDOW_SIZE - config.CHUNK_WINDOW_OVERLAP);
