324	/**
325	 * Find the line index of the closing brace that matches the function body's
326	 * opening brace, starting from the given line. Returns -1 if not found.
327	 *
328	 * IMPORTANT: skips the parameter list on the first line so that empty default
329	 * parameters like `constructor(config = {})` don't trip the brace counter.
330	 * The body's opening brace is the FIRST `{` that comes after the closing `)`
331	 * of the parameter list on the start line. Counting begins from that brace.
332	 */
333	function findMatchingBrace(lines, startLineIndex) {
334	  let depth = 0;
335	  let foundOpen = false;
336	  let inString = false;
337	  let stringChar = null;
338	  let inComment = false;
339	
340	  // Find the body-opening brace position on the start line.
341	  // It's the first `{` that comes after the closing `)` of the parameter list.
342	  const startLine = lines[startLineIndex];
343	  let startCol = 0;
344	  const closeParenIdx = startLine.lastIndexOf(')');
345	  if (closeParenIdx !== -1) {
346	    const braceIdx = startLine.indexOf('{', closeParenIdx);
347	    if (braceIdx !== -1) {
348	      startCol = braceIdx;
349	    }
350	  }
351	
352	  for (let i = startLineIndex; i < lines.length; i++) {
353	    const line = lines[i];
354	    // First line starts at the body brace; subsequent lines start at column 0.
355	    const colStart = (i === startLineIndex) ? startCol : 0;
356	
357	    for (let j = colStart; j < line.length; j++) {
358	      const ch = line[j];
359	      const next = line[j + 1];
360	
361	      // Very light-touch string/comment handling — not a full JS parser
362	      if (inComment) {
363	        if (ch === '*' && next === '/') {
364	          inComment = false;
365	          j++;
366	        }
367	        continue;
368	      }
369	      if (inString) {
370	        if (ch === '\\') { j++; continue; }
371	        if (ch === stringChar) { inString = false; stringChar = null; }
372	        continue;
373	      }
374	      if (ch === '/' && next === '/') break;        // line comment — skip rest of line
375	      if (ch === '/' && next === '*') { inComment = true; j++; continue; }
376	      if (ch === '"' || ch === "'" || ch === '`') {
377	        inString = true;
378	        stringChar = ch;
379	        continue;
380	      }
381	
382	      if (ch === '{') {
383	        depth++;
384	        foundOpen = true;
385	      } else if (ch === '}') {
386	        depth--;
387	        if (foundOpen && depth === 0) {
388	          return i;
389	        }
390	      }
391	    }
392	  }
393	  return -1;
394	}
