416	      windows.forEach((winText, idx) => {
417	        chunks.push({
418	          kind: 'doc_section',
419	          name: `${currentHeader || 'root'}#part${idx + 1}`,
420	          start_line: currentStartLine,
421	          end_line: currentStartLine + currentBody.length - 1,
422	          text: winText,
