448	  }
449	  flush();
450	
451	  // Fallback: if no headers at all, sliding window the whole file
452	  if (chunks.length === 0) {
453	    const windows = slidingWindow(text, config.CHUNK_WINDOW_SIZE, config.CHUNK_WINDOW_OVERLAP);
454	    windows.forEach((winText, idx) => {
455	      const charsBeforeStart = idx * (config.CHUNK_WINDOW_SIZE - config.CHUNK_WINDOW_OVERLAP);
456	      const startLine = text.slice(0, charsBeforeStart).split('\n').length;
457	      const endLine = startLine + winText.split('\n').length - 1;
458	      chunks.push({
459	        kind: 'doc_section',
460	        name: `window_${idx + 1}`,
461	        start_line: startLine,
462	        end_line: endLine,
463	        text: winText,
464	      });
465	    });
466	  }
