488	    if (!line) continue;
489	
490	    let record;
491	    try {
492	      record = JSON.parse(line);
493	    } catch (err) {
494	      console.warn(`[chunkJsonl] ${filePath}:${i + 1} parse error: ${err.message.slice(0, 80)}`);
495	      continue;
496	    }
