498	    // Build a human-readable text representation
499	    const headerParts = [];
500	    if (record.id) headerParts.push(`ID: ${record.id}`);
501	    if (record.date) headerParts.push(`Date: ${record.date}`);
502	    if (record.severity) headerParts.push(`Severity: ${record.severity}`);
503	    if (Array.isArray(record.tags) && record.tags.length > 0) {
