511	    // Guard oversized records
512	    if (chunkText.length > config.MAX_CHUNK_CHARS) {
513	      const windows = slidingWindow(chunkText, config.CHUNK_WINDOW_SIZE, config.CHUNK_WINDOW_OVERLAP);
