515	        chunks.push({
516	          kind: 'jsonl_record',
517	          name: `${record.id || `line_${i + 1}`}#part${idx + 1}`,
518	          start_line: i + 1,
519	          end_line: i + 1,
520	          text: winText,
521	        });
522	      });
523	    } else {
524	      chunks.push({
525	        kind: 'jsonl_record',
526	        name: record.id || `line_${i + 1}`,
527	        start_line: i + 1,
528	        end_line: i + 1,
529	        text: chunkText,
530	      });
