537	/**
538	 * Sliding window chunker for files without a structural chunker.
539	 */
540	function slidingWindow(text, windowSize, overlap) {
541	  const chunks = [];
542	  const step = windowSize - overlap;
543	  if (step <= 0) throw new Error('overlap must be less than windowSize');
544	
545	  for (let start = 0; start < text.length; start += step) {
546	    const end = Math.min(start + windowSize, text.length);
547	    chunks.push(text.slice(start, end));
548	    if (end === text.length) break;
549	  }
550	  return chunks;
551	}
