740	/**
741	 * Pack chunks into batches that fit within the per-request token budget
742	 * AND a maximum chunk count per batch. Returns an array of batches, each
743	 * a list of chunk indices into the source array.
744	 */
745	function packBatches(chunks, maxTokensPerBatch, maxChunksPerBatch) {
746	  const batches = [];
747	  let current = [];
748	  let currentTokens = 0;
749	
750	  for (let i = 0; i < chunks.length; i++) {
751	    const chunkTokens = estimateTokens(chunks[i].text);
752	    // If adding this chunk would exceed limits, flush the current batch
753	    if (current.length > 0 &&
754	        (currentTokens + chunkTokens > maxTokensPerBatch ||
755	         current.length >= maxChunksPerBatch)) {
756	      batches.push(current);
757	      current = [];
758	      currentTokens = 0;
759	    }
760	    current.push(i);
761	    currentTokens += chunkTokens;
762	  }
763	  if (current.length > 0) batches.push(current);
764	  return batches;
765	}
