const db2 = db.getSiblingDB("ogz_knowledge");
const chunks = db2.getCollection("chunks_local_nomic");
// dimension distribution
const dims = chunks.aggregate([
  {$project: {d: {$size: {$ifNull: ["$embedding", []]}}}},
  {$group: {_id: "$d", n: {$sum: 1}}},
  {$sort: {n: -1}}
]).toArray();
print("dims_distribution:", JSON.stringify(dims));
// does any doc carry an embed index id field?
const withId = chunks.findOne({embed_index_id: {$exists: true}}, {embed_index_id: 1, file_path: 1});
print("embed_index_id_sample:", JSON.stringify(withId));
// indexed_at range
const newest = chunks.find({}, {indexed_at: 1, _id: 0}).sort({indexed_at: -1}).limit(1).toArray();
const oldest = chunks.find({}, {indexed_at: 1, _id: 0}).sort({indexed_at: 1}).limit(1).toArray();
print("indexed_at_newest:", JSON.stringify(newest), "oldest:", JSON.stringify(oldest));
// duplicate file_path+start_line pairs
const dup = chunks.aggregate([
  {$group: {_id: {f: "$file_path", s: "$start_line", k: "$kind"}, n: {$sum: 1}}},
  {$match: {n: {$gt: 1}}},
  {$count: "duplicated_positions"}
]).toArray();
print("duplicated_positions:", JSON.stringify(dup));
// legacy collections
print("legacy_chunks_count:", db2.getCollection("chunks").countDocuments());
print("legacy_traces_count:", db2.getCollection("investigation_traces").countDocuments());
print("refresh_chunks_count:", db2.getCollection("chunks_local_nomic_refresh_20260603").countDocuments());
const stats2 = db2.getCollection("index_stats_local_nomic").find().sort({run_at: -1}).limit(3).toArray();
print("recent_index_stats:", JSON.stringify(stats2.map(s => ({run_at: s.run_at, files: s.files_walked, chunks: s.chunks_produced}))));
